    if (v.sha256 && v.sha256.toLowerCase() !== d256) throw new Error("sha256 mismatch vs provider digest");

    // Bulk filling must never push out MORE popular files to make room for a less
    // popular one: only mirrored mods with <= downloads (or untouched for 30 days) are evictable.
    try {
      await ensureRoom(bytes, v.id, v.gameMod.downloads ?? 0);
    } catch (e) {
      await fs.rm(tmp, { force: true }).catch(() => {});
      if (e instanceof MirrorFullError) return { outcome: "FULL", reason: e.message };
