    });
    return { outcome: "OK" };
  } catch (e) {
    await fs.rm(tmp, { force: true }).catch(() => {});
    const reason = e instanceof Error ? e.message : String(e);
    await db.modVersion.update({ where: { id: v.id }, data: { mirrorState: "FAILED", mirrorError: reason.slice(0, 500) } }).catch(() => {});
    return { outcome: "FAILED", reason };
  }
}

async function resolveLocalQuiet(rel: string, bytes?: number | null): Promise<boolean> {
  try {
    const st = await fs.stat(blobAbs(rel));
    return bytes == null || st.size === bytes;
  } catch {
    return false;
  }
}

/** Sum of distinct blob bytes currently held (dedupe-aware). */
export async function mirrorUsage(): Promise<{ files: number; bytes: number; budget: number }> {
  const rows = await db.$queryRaw<{ files: bigint; bytes: bigint | null }[]>`
    select count(*)::bigint as files, coalesce(sum(b),0)::bigint as bytes
    from (select distinct on ("mirrorPath") "mirrorPath", "mirrorBytes" as b from "ModVersion" where "mirrorState"='OK') x`;
  return { files: Number(rows[0]?.files ?? 0), bytes: Number(rows[0]?.bytes ?? 0), budget: mirrorMaxBytes() };
}

/**
 * Eviction policy: when adding `incoming` bytes would exceed the budget, drop
 * the least valuable blobs first — ordered by last access (never-read files
 * fall back to their mirror time), then by the parent mod's download count
 * (popular mods are kept longer). A blob shared by several versions is only
 * unlinked when the last referencing row is evicted.
 */
export class MirrorFullError extends Error {}

export async function ensureRoom(incoming: number, excludeId?: string, incomingDownloads = Number.MAX_SAFE_INTEGER): Promise<number> {
  const budget = mirrorMaxBytes();
  let { bytes } = await mirrorUsage();
  let evicted = 0;
  while (bytes + incoming > budget) {
    const victim = await db.$queryRaw<{ id: string; mirrorPath: string; mirrorBytes: number }[]>`
      select v.id, v."mirrorPath", v."mirrorBytes" from "ModVersion" v join "GameMod" m on m.id=v."gameModId"
      where v."mirrorState"='OK' and v.id <> ${excludeId ?? ""}
        and (coalesce(m.downloads,0) <= ${incomingDownloads} or coalesce(v."lastAccessedAt", v."mirroredAt") < now() - interval '30 days')
      order by coalesce(v."lastAccessedAt", v."mirroredAt") asc nulls first, coalesce(m.downloads,0) asc
      limit 1`;
    if (!victim.length) throw new MirrorFullError("mirror budget full; nothing less popular to evict");
    const vv = victim[0];
    await db.modVersion.update({ where: { id: vv.id }, data: { mirrorState: "EVICTED", mirrorPath: null, mirrorBytes: null } });
    const still = await db.modVersion.count({ where: { mirrorState: "OK", mirrorPath: vv.mirrorPath } });
    if (still === 0) {
      await fs.rm(blobAbs(vv.mirrorPath), { force: true }).catch(() => {});
      bytes -= vv.mirrorBytes;
    }
    evicted++;
  }
  return evicted;
}

/** Re-hash stored blobs (oldest-verified first is overkill here: caller passes a limit). */
export async function verifyMirror(limit = 50): Promise<{ checked: number; corrupt: number }> {
  const rows = await db.modVersion.findMany({ where: { mirrorState: "OK" }, take: limit, orderBy: { mirroredAt: "asc" }, select: { id: true, mirrorPath: true, mirrorSha256: true } });
  let corrupt = 0;
  for (const r of rows) {
    if (!r.mirrorPath || !r.mirrorSha256) continue;
    let ok = false;
    try {
      const h = createHash("sha256");
      await pipeline(createReadStream(blobAbs(r.mirrorPath)), async function (src) { for await (const c of src) h.update(c as Buffer); });
      ok = h.digest("hex") === r.mirrorSha256;
    } catch {}
    if (!ok) {
      corrupt++;
      await db.modVersion.update({ where: { id: r.id }, data: { mirrorState: "FAILED", mirrorError: "integrity check failed", mirrorPath: null } });
    }
  }
  return { checked: rows.length, corrupt };
}
