1	"use client";
2	
3	import { useMemo, useState, useTransition } from "react";
4	import { useRouter } from "next/navigation";
5	import { saveGameConfig } from "@/lib/actions-game-config";
6	import type { ConfigField, FamilySchema } from "@/lib/game-config";
7	import { SearchableSelect } from "@/components/customer/SearchableSelect";
8	
9	type Values = Record<string, string | number | boolean>;
10	
11	/**
12	 * Dynamic per-game settings form. Renders the family schema (grouped fields, the
13	 * right widget per type) plus a variant/loader picker, and persists via
14	 * `saveGameConfig` — which validates, stores the values and enqueues a
15	 * GAME_CONFIG job to apply them.
16	 */
17	export function GameSettings({
18	  serverId,
19	  schema,
20	  variant: initialVariant,
21	  values: initialValues,
22	  disabled,
23	  canApply,
24	}: {
25	  serverId: string;
26	  schema: FamilySchema;
27	  variant: string;
28	  values: Values;
29	  disabled?: boolean;
30	  /** Whether the worker can actually WRITE these to the game server. */
31	  canApply: boolean;
32	}) {
33	  const router = useRouter();
34	  const [variant, setVariant] = useState(initialVariant);
35	  const [values, setValues] = useState<Values>(initialValues);
36	  const [error, setError] = useState<string | null>(null);
37	  const [saved, setSaved] = useState(false);
38	  const [pending, start] = useTransition();
39	
40	  // Fields grouped by their `group` heading, preserving declaration order.
41	  const groups = useMemo(() => {
42	    const map = new Map<string, ConfigField[]>();
43	    for (const f of schema.fields) {
44	      if (!map.has(f.group)) map.set(f.group, []);
45	      map.get(f.group)!.push(f);
46	    }
47	    return [...map.entries()];
48	  }, [schema]);
49	
50	  function set(key: string, value: string | number | boolean) {
51	    setValues((v) => ({ ...v, [key]: value }));
52	    setSaved(false);
53	  }
54	
55	  function save() {
56	    start(async () => {
57	      setError(null);
58	      setSaved(false);
59	      const res = await saveGameConfig(serverId, variant, values);
60	      if (res?.error) setError(res.error);
61	      else {
62	        setSaved(true);
63	        router.refresh();
64	      }
65	    });
66	  }
67	
68	  const activeVariant = schema.variants.find((v) => v.id === variant);
69	
70	  return (
71	    <div className="card">
72	      {/* Said BEFORE the customer types, not after the job fails. The worker
73	          throws a customer-facing "your settings are NOT in effect" for every
74	          family outside REAL_APPLY_FAMILIES — 39 of 43 — and until now this
75	          form accepted the save and reported "queued for apply" regardless. */}
76	      {!canApply && (
77	        <div className="mb-4 rounded-xl border border-amber-500/35 bg-amber-500/10 px-3.5 py-3 text-sm leading-relaxed text-amber-300">
78	          <strong className="font-semibold">These settings can&apos;t be pushed to {schema.label} yet.</strong>{" "}
79	          We&apos;ll save them, but writing them into the running server is only wired for some games so
80	          far and yours isn&apos;t one of them. Edit the config file directly in the{" "}
81	          <strong className="text-amber-200">Files</strong> tab and restart from{" "}
82	          <strong className="text-amber-200">Console</strong>, or ask support and we&apos;ll do it.
83	        </div>
84	      )}
85	      <div className="flex flex-wrap items-start justify-between gap-4">
86	        <div>
87	          <h2 className="font-semibold">Game settings</h2>
88	          <p className="mt-1 max-w-xl text-sm text-slate-400">
89	            Configure your {schema.label} server. Changes are queued and applied to the server —
90	            some settings only take effect after the next restart.
91	          </p>
92	        </div>
93	        <button className="btn-primary" disabled={pending || disabled} onClick={save}>
94	          {pending ? "Saving…" : "Save & apply"}
95	        </button>
96	      </div>
97	
98	      {/* Variant / loader picker */}
99	      <div className="mt-5">
100	        <label className="block text-sm">
101	          <span className="mb-1.5 block font-medium">Server type</span>
102	          <select
103	            className="input"
104	            value={variant}
105	            disabled={pending || disabled}
106	            onChange={(e) => {
107	              setVariant(e.target.value);
108	              setSaved(false);
109	            }}
110	          >
111	            {schema.variants.map((v) => (
112	              <option key={v.id} value={v.id}>
113	                {v.label}
114	              </option>
115	            ))}
116	          </select>
117	        </label>
118	        {activeVariant?.description && (
119	          <p className="mt-1.5 text-xs text-slate-500">{activeVariant.description}</p>
120	        )}
121	      </div>
122	
123	      {groups.map(([group, fields]) => (
124	        <div key={group} className="mt-6">
125	          <p className="section-label">{group}</p>
126	          <div className="mt-3 grid gap-4 sm:grid-cols-2">
127	            {fields.map((f) => (
128	              <Field
129	                key={f.key}
130	                field={f}
131	                value={values[f.key]}
132	                disabled={pending || disabled}
133	                onChange={(val) => set(f.key, val)}
134	              />
135	            ))}
136	          </div>
137	        </div>
138	      ))}
139	
140	      <div className="mt-5 flex flex-wrap items-center gap-3">
141	        <button className="btn-primary" disabled={pending || disabled} onClick={save}>
142	          {pending ? "Saving…" : "Save & apply"}
143	        </button>
144	        {saved && !error && <span className="text-sm text-emerald-400">Settings queued for apply.</span>}
145	        {error && <span className="text-sm text-red-400">{error}</span>}
146	      </div>
147	    </div>
148	  );
149	}
150	
151	function Field({
152	  field,
153	  value,
154	  disabled,
155	  onChange,
156	}: {
157	  field: ConfigField;
158	  value: string | number | boolean | undefined;
159	  disabled?: boolean;
160	  onChange: (v: string | number | boolean) => void;
161	}) {
162	  const isMissing = !!field.required && String(value ?? field.default ?? "").trim() === "";
163	  const labelRow = (
164	    <span className="mb-1.5 flex items-baseline justify-between gap-2">
165	      <span className="font-medium">{field.label}</span>
166	      {field.required ? (
167	        <span
168	          className={`text-[10px] font-semibold uppercase tracking-wide ${isMissing ? "text-red-300" : "text-emerald-400"}`}
169	        >
170	          {isMissing ? "Required — server won't start without this" : "Required ✓"}
171	        </span>
172	      ) : (
173	        field.phase === "deploy" && (
174	          <span className="text-[10px] uppercase tracking-wide text-amber-300/80">restart</span>
175	        )
176	      )}
177	    </span>
178	  );
179	
180	  if (field.type === "bool") {
181	    const on = value === true;
182	    return (
183	      <div className="flex items-center justify-between gap-4 rounded-xl border border-white/[0.06] bg-navy-950/40 px-3.5 py-3">
184	        <span className="text-sm">
185	          <span className="font-medium">{field.label}</span>
186	          {field.help && <span className="mt-0.5 block text-xs text-slate-500">{field.help}</span>}
187	        </span>
188	        <button
189	          type="button"
190	          role="switch"
191	          aria-checked={on}
192	          disabled={disabled}
193	          onClick={() => onChange(!on)}
194	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
195	            on ? "bg-brand-500" : "bg-white/15"
196	          } ${disabled ? "opacity-60" : ""}`}
197	        >
198	          <span
199	            className={`inline-block h-5 w-5 transform rounded-full bg-[#fff] shadow transition-transform ${
200	              on ? "translate-x-5" : "translate-x-0.5"
201	            }`}
202	          />
203	        </button>
204	      </div>
205	    );
206	  }
207	
208	  return (
209	    <label className="block text-sm">
210	      {labelRow}
211	      {field.type === "enum" && field.searchable ? (
212	        <SearchableSelect
213	          options={field.options ?? []}
214	          value={String(value ?? field.default)}
215	          disabled={disabled}
216	          onChange={onChange}
217	          placeholder={`Search ${field.label.toLowerCase()}…`}
218	        />
219	      ) : field.type === "enum" ? (
220	        <select
221	          className="input"
222	          value={String(value ?? field.default)}
223	          disabled={disabled}
224	          onChange={(e) => onChange(e.target.value)}
225	        >
226	          {field.options?.map((o) => (
227	            <option key={o.value} value={o.value}>
228	              {o.label}
229	            </option>
230	          ))}
231	        </select>
232	      ) : field.type === "int" ? (
233	        <input
234	          className="input"
235	          type="number"
236	          value={value === undefined || value === null ? Number(field.default) : Number(value)}
237	          min={field.min}
238	          max={field.max}
239	          step={1}
240	          disabled={disabled}
241	          onChange={(e) => onChange(e.target.value === "" ? "" as any : Number(e.target.value))}
242	        />
243	      ) : (
244	        <input
245	          className={`input ${isMissing ? "border-red-400/60 focus:border-red-400" : ""}`}
246	          type="text"
247	          value={String(value ?? field.default)}
248	          maxLength={256}
249	          disabled={disabled}
250	          aria-invalid={isMissing}
251	          onChange={(e) => onChange(e.target.value)}
252	        />
253	      )}
254	      {field.help && (
255	        <span className={`mt-1 block text-xs ${isMissing ? "text-red-300" : "text-slate-500"}`}>{field.help}</span>
256	      )}
257	    </label>
258	  );
259	}
