/**
 * Minecraft server-software mirror — shared types.
 *
 * See docs/DOCUMENTATION.md § "Minecraft server-software mirror" for the
 * layout, jobs, serving path and fallback behaviour. Everything in lib/mcjars
 * is I/O-light and testable: providers expose PURE parsers (fed recorded
 * fixtures in test/mcjars.test.ts) plus a thin fetch wrapper.
 */

/** Every server-software type the mirror knows. Not all are orderable (see ORDERABLE_TYPES). */
export const MC_TYPES = [
  "vanilla",
  "paper",
  "folia",
  "velocity",
  "purpur",
  "fabric",
  "quilt",
  "forge",
  "neoforge",
  "bedrock",
] as const;
export type McType = (typeof MC_TYPES)[number];

export function isMcType(s: unknown): s is McType {
  return typeof s === "string" && (MC_TYPES as readonly string[]).includes(s);
}

/**
 * The Java-edition types a customer can order today — 1:1 with
 * lib/game-config.ts's MINECRAFT.variants ids. folia/neoforge/quilt/velocity are
 * mirrored (so a future variant is a one-line add) but not orderable yet.
 */
export const ORDERABLE_TYPES = ["vanilla", "paper", "purpur", "fabric", "forge"] as const;
export type OrderableType = (typeof ORDERABLE_TYPES)[number];

export type Channel = "stable" | "experimental";

export type HashAlgo = "sha1" | "sha256" | "sha512" | "md5";

/**
 * One downloadable artifact as an upstream describes it, BEFORE we have it.
 * `build` is the type's own build identity: Paper's build number, Forge's
 * loader version, Fabric's "<loader>+<installer>", Mojang's version id.
 */
export interface Candidate {
  type: McType;
  mcVersion: string;
  build: string;
  channel: Channel;
  fileName: string;
  url: string;
  /** Upstream-published digest when one exists (Mojang sha1, Paper sha256, Purpur md5, maven .sha256/.sha1). */
  upstreamHash?: { algo: HashAlgo; value: string } | null;
  /** Hash sidecar URL to fetch at download time (maven .sha256/.sha1) when not inline. */
  hashUrl?: { algo: HashAlgo; url: string }[];
  size?: number | null;
  publishedAt?: string | null;
  /** Free-form per-type detail (loader/installer versions, java minimum...). */
  extra?: Record<string, string | number | boolean>;
}

/** A build as recorded in `<root>/<type>/index.json`. */
export interface IndexBuild {
  build: string;
  channel: Channel;
  fileName: string;
  sourceUrl: string;
  upstreamHash?: { algo: HashAlgo; value: string } | null;
  size?: number | null;
  publishedAt?: string | null;
  extra?: Record<string, string | number | boolean>;
  /** Set once the file is on disk and verified. */
  sha256?: string | null;
  mirrored: boolean;
  fetchedAt?: string | null;
  verifiedAt?: string | null;
  lastError?: string | null;
}

export interface IndexVersion {
  /** stable = a real release line; experimental = pre-release / beta-only line. */
  channel: Channel;
  /** Newest build id we know of (any channel). */
  latestBuild: string | null;
  /** Newest STABLE build id (what "latest" resolves to). */
  latestStableBuild: string | null;
  /** Newest first. Bounded: only the most recent builds + any mirrored ones are kept. */
  builds: IndexBuild[];
  releasedAt?: string | null;
  javaMin?: number | null;
}

export interface TypeIndex {
  schema: 1;
  type: McType;
  updatedAt: string;
  /** Which upstream API produced the metadata (e.g. "fill-v3", "papermc-v2"). */
  source: string;
  /** Newest first (by the type's own version ordering). */
  order: string[];
  versions: Record<string, IndexVersion>;
  /** Conditional-request state, keyed by URL. */
  http?: Record<string, { etag?: string | null; lastModified?: string | null }>;
}

export interface GlobalManifest {
  schema: 1;
  updatedAt: string;
  types: Record<
    string,
    { updatedAt: string; versions: number; mirroredFiles: number; mirroredBytes: number; newest: string | null; newestBuild: string | null }
  >;
  totalBytes: number;
}

/** What a provider returns from one metadata pass. */
export interface ProviderResult {
  source: string;
  /** Newest-first version list with channel. */
  versions: { mcVersion: string; channel: Channel; releasedAt?: string | null; javaMin?: number | null }[];
  /** Candidates to keep metadata for (newest builds per version). */
  candidates: Candidate[];
  /** true = upstream answered 304 for the top-level listing: keep the previous index untouched. */
  notModified?: boolean;
  http?: TypeIndex["http"];
}

