import fs from "node:fs/promises";
import path from "node:path";

/**
 * Where the Minecraft mirror lives.
 *
 *   MC_MIRROR_DIR                 explicit root (wins)
 *   NXLABS_MIRROR_DIR/minecraft   shared NX Labs dataset convention (K2's lib/modsync)
 *   /tank/nxlabs-mirror/minecraft default (3 TB `tank` pool, NOT the 49 GB root disk)
 *
 * The code NEVER creates the dataset root (`NXLABS_MIRROR_DIR`, or the parent of
 * MC_MIRROR_DIR). If it is missing the mirror is OFF and every consumer falls
 * back to the old upstream behaviour: creating it ourselves on a host where
 * /tank isn't mounted would silently fill `/`. The `minecraft/` subdirectory
 * itself is created on demand only when its parent already exists.
 *
 * Owner setup (once):
 *   zfs create -o quota=100G -o mountpoint=/tank/nxlabs-mirror tank/nxlabs-mirror
 *   chown nxeon:nxeon /tank/nxlabs-mirror
 */
export function datasetRoot(): string {
  return process.env.NXLABS_MIRROR_DIR || "/tank/nxlabs-mirror";
}

export function mirrorRoot(): string {
  return process.env.MC_MIRROR_DIR || path.join(datasetRoot(), "minecraft");
}

/** Bytes the Minecraft mirror may use (it shares the dataset with NX Labs mod files). Default 40 GiB. */
export function mirrorMaxBytes(): number {
  const v = Number(process.env.MC_MIRROR_MAX_BYTES);
  return Number.isFinite(v) && v > 0 ? v : 40 * 1024 ** 3;
}

/** Newest builds kept per HOT version (in use by a Server, or among the newest few versions). */
export function keepBuildsHot(): number {
  const v = Number(process.env.MC_MIRROR_KEEP_BUILDS);
  return Number.isInteger(v) && v >= 1 && v <= 20 ? v : 2;
}

/** How many of each type's newest versions count as "hot". */
export function hotVersionCount(): number {
  const v = Number(process.env.MC_MIRROR_HOT_VERSIONS);
  return Number.isInteger(v) && v >= 1 && v <= 50 ? v : 6;
}

/**
 * "all" (default) = latest stable build of EVERY version is downloaded (an
 * outage can't block any orderable combo); "hot" = only hot versions are
 * downloaded, everything else is metadata-only (smaller, ~1/4 the bytes).
 */
export function versionScope(): "all" | "hot" {
  return process.env.MC_MIRROR_SCOPE === "hot" ? "hot" : "all";
}

/** Mirror is globally disabled (kill switch). */
export function mirrorDisabled(): boolean {
  return process.env.MC_MIRROR_DISABLED === "1";
}

/** Public base URL guests download from (they reach nxeon.cloud via NAT/hairpin). */
export function publicBaseUrl(): string {
  return (process.env.MC_MIRROR_PUBLIC_URL || process.env.APP_URL || "https://nxeon.cloud").replace(/\/+$/, "");
}

/** Root-relative tmp dir for in-flight downloads (same filesystem → atomic rename). */
export const tmpDir = () => path.join(mirrorRoot(), ".tmp");

let readyCache: { at: number; ok: boolean; root: string } | null = null;

/**
 * The mirror is usable only if the dataset root already exists (we never make it).
