/**
 * Polite HTTP for the Minecraft upstreams (Mojang, PaperMC, Purpur, Fabric,
 * Quilt, Forge, NeoForge). Same shape as lib/modsync/http.ts (K2) but kept
 * separate so this mirror never depends on that branch:
 *  - identifying User-Agent with a contact URL (PaperMC's and Fabric's API
 *    docs both ask for one; Mojang/maven hosts are static CDNs);
 *  - per-host pacing (token-bucket style gap), so one provider can never
 *    hammer an upstream even if a bug loops;
 *  - exponential backoff with jitter on 429/5xx/network errors, honouring
 *    Retry-After;
 *  - ETag / If-Modified-Since conditional GETs (304 → "unchanged").
 */

export const MCMIRROR_UA = "NxeonMcMirror/1.0 (+https://nxeon.cloud; ops@nxeon.cloud)";

export class HttpError extends Error {
  constructor(public status: number, public url: string, msg?: string) {
    super(msg ?? `HTTP ${status} for ${url}`);
  }
}

export interface HttpOptions {
  /** Max requests per minute per host. */
  ratePerMin?: number;
  maxRetries?: number;
  fetchImpl?: typeof fetch;
  sleep?: (ms: number) => Promise<void>;
  now?: () => number;
  /** Abort everything after this epoch-ms (per-provider timeout). */
  deadline?: number;
}

export interface Cond {
  etag?: string | null;
  lastModified?: string | null;
}

export class McHttp {
  private nextSlot = new Map<string, number>();
  private readonly gap: number;
  readonly fetchImpl: typeof fetch;
  private readonly sleep: (ms: number) => Promise<void>;
  private readonly now: () => number;
  requests = 0;
  retries = 0;
  deadline?: number;

  constructor(private opts: HttpOptions = {}) {
    this.gap = Math.ceil(60_000 / Math.max(1, opts.ratePerMin ?? 60));
    this.fetchImpl = opts.fetchImpl ?? fetch;
    this.sleep = opts.sleep ?? ((ms) => new Promise((r) => setTimeout(r, ms)));
    this.now = opts.now ?? Date.now;
    this.deadline = opts.deadline;
  }

  private checkDeadline() {
    if (this.deadline && this.now() > this.deadline) throw new Error("provider time budget exhausted");
  }

  private async pace(url: string) {
    let host = "";
    try {
      host = new URL(url).host;
    } catch {
      /* invalid URL → fetch will throw */
    }
    const t = this.now();
    const slot = this.nextSlot.get(host) ?? 0;
    const wait = Math.max(0, slot - t);
    this.nextSlot.set(host, Math.max(t, slot) + this.gap);
    if (wait > 0) await this.sleep(wait);
  }

  /** Backoff for attempt n (0-based): 1s, 2s, 4s… capped 60s, plus jitter; Retry-After wins (capped 120s). */
  static backoffMs(attempt: number, retryAfter?: string | null, rnd: () => number = Math.random): number {
    if (retryAfter) {
      const s = Number(retryAfter);
      if (Number.isFinite(s) && s >= 0) return Math.min(120_000, s * 1000 + 250);
      const d = Date.parse(retryAfter);
      if (Number.isFinite(d)) return Math.min(120_000, Math.max(0, d - Date.now()) + 250);
    }
    return Math.min(60_000, 1000 * 2 ** attempt) + Math.floor(rnd() * 400);
  }

  async request(
    url: string,
    init: RequestInit & { cond?: Cond; maxRetries?: number; timeoutMs?: number } = {},
  ): Promise<Response> {
    if (!/^https:\/\//i.test(url)) throw new Error(`refusing non-https upstream URL: ${url}`);
    const maxRetries = init.maxRetries ?? this.opts.maxRetries ?? 4;
    const headers: Record<string, string> = {
      "User-Agent": MCMIRROR_UA,
      Accept: "application/json",
      ...((init.headers as Record<string, string>) ?? {}),
    };
    if (init.cond?.etag) headers["If-None-Match"] = init.cond.etag;
    if (init.cond?.lastModified) headers["If-Modified-Since"] = init.cond.lastModified;
    let lastErr: unknown;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      this.checkDeadline();
      await this.pace(url);
      this.requests++;
      try {
        const res = await this.fetchImpl(url, {
          ...init,
          headers,
          redirect: "follow",
          signal: init.signal ?? AbortSignal.timeout(init.timeoutMs ?? 30_000),
        });
        if (res.status === 429 || res.status >= 500) {
          lastErr = new HttpError(res.status, url);
          try {
            await res.arrayBuffer();
          } catch {
            /* drain */
          }
          if (attempt === maxRetries) throw lastErr;
          this.retries++;
          await this.sleep(McHttp.backoffMs(attempt, res.headers.get("retry-after")));
          continue;
        }
        return res;
      } catch (e) {
        if (e instanceof HttpError) throw e;
        lastErr = e;
        if (attempt === maxRetries) throw e;
        this.retries++;
        await this.sleep(McHttp.backoffMs(attempt));
      }
    }
    throw lastErr;
  }

  async json<T>(url: string, init: RequestInit & { maxRetries?: number } = {}): Promise<T> {
    const res = await this.request(url, init);
    if (!res.ok) throw new HttpError(res.status, url);
    return (await res.json()) as T;
  }

  async text(url: string, init: RequestInit & { maxRetries?: number } = {}): Promise<string> {
    const res = await this.request(url, { ...init, headers: { Accept: "*/*", ...((init.headers as Record<string, string>) ?? {}) } });
    if (!res.ok) throw new HttpError(res.status, url);
    return await res.text();
  }

  /** Conditional GET returning parsed JSON, or null on 304. */
  async jsonCond<T>(url: string, cond: Cond | undefined): Promise<{ data: T; etag: string | null; lastModified: string | null } | null> {
    const res = await this.request(url, { cond });
    if (res.status === 304) return null;
    if (!res.ok) throw new HttpError(res.status, url);
    return { data: (await res.json()) as T, etag: res.headers.get("etag"), lastModified: res.headers.get("last-modified") };
  }

  /** Conditional GET returning text, or null on 304. */
  async textCond(url: string, cond: Cond | undefined): Promise<{ data: string; etag: string | null; lastModified: string | null } | null> {
    const res = await this.request(url, { cond, headers: { Accept: "*/*" } });
    if (res.status === 304) return null;
    if (!res.ok) throw new HttpError(res.status, url);
    return { data: await res.text(), etag: res.headers.get("etag"), lastModified: res.headers.get("last-modified") };
  }
}

