/**
 * Version helpers shared by providers, availability checks and the UI.
 * Pure — safe to import from client components.
 */

/** "1.21.11" / "26.2" → [1,21,11] / [26,2]; null for anything non-numeric ("26.4-snapshot-1", "LATEST"). */
export function parseRelease(v: string): number[] | null {
  if (!/^\d+(\.\d+){0,3}$/.test(v)) return null;
  return v.split(".").map(Number);
}

/** Compare two release strings (numeric dotted). Non-numeric strings sort below numeric ones, then lexically. */
export function compareMcVersions(a: string, b: string): number {
  const pa = parseRelease(a);
  const pb = parseRelease(b);
  if (pa && pb) {
    const len = Math.max(pa.length, pb.length);
    for (let i = 0; i < len; i++) {
      const d = (pa[i] ?? 0) - (pb[i] ?? 0);
      if (d !== 0) return d;
    }
    return 0;
  }
  if (pa) return 1;
  if (pb) return -1;
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Newest-first sort. */
export function sortVersionsDesc(vs: string[]): string[] {
  return [...vs].sort((a, b) => compareMcVersions(b, a));
}

/** Compare dotted build/loader versions like "52.1.16", "0.19.5", "21.1.209", "2633". Numeric-aware. */
export function compareBuilds(a: string, b: string): number {
  const ta = a.split(/[.+-]/);
  const tb = b.split(/[.+-]/);
  const len = Math.max(ta.length, tb.length);
  for (let i = 0; i < len; i++) {
    const x = ta[i] ?? "";
    const y = tb[i] ?? "";
    const nx = /^\d+$/.test(x) ? Number(x) : NaN;
    const ny = /^\d+$/.test(y) ? Number(y) : NaN;
    if (!Number.isNaN(nx) && !Number.isNaN(ny)) {
      if (nx !== ny) return nx - ny;
    } else if (x !== y) {
      // a missing segment (shorter) sorts first; "beta" sorts before numbers
      if (x === "") return -1;
      if (y === "") return 1;
      if (!Number.isNaN(nx)) return 1;
      if (!Number.isNaN(ny)) return -1;
      return x < y ? -1 : 1;
    }
  }
  return 0;
}

/**
 * NeoForge's own version → the Minecraft version it targets.
 *   20.2.x / 20.4.x / 21.0.x / 21.1.x  →  1.20.2 / 1.20.4 / 1.21 / 1.21.1
 *   26.1.0.x / 26.1.2.x / 26.3.0.x     →  26.1   / 26.1.2 / 26.3      (year-based MC versions)
 * Returns null for things that aren't a real MC line (April-fools "0.25w14craftmine.3-beta").
 */
export function neoforgeToMc(neo: string): string | null {
  const core = neo.replace(/-beta$|-alpha$/, "");
  const parts = core.split(".");
  if (!parts.every((p) => /^\d+$/.test(p))) return null;
  const n = parts.map(Number);
  if (n[0] >= 25) {
    // year.drop.hotfix.build
    if (n.length < 4) return null;
    return n[2] === 0 ? `${n[0]}.${n[1]}` : `${n[0]}.${n[1]}.${n[2]}`;
  }
  if (n[0] >= 20 && n.length >= 3) {
    return n[1] === 0 ? `1.${n[0]}` : `1.${n[0]}.${n[1]}`;
  }
  return null;
}

/**
 * Closest available version to `want` (prefers the newest version that is
 * <= want within the same major line, then the nearest newer one). Used for
 * the "not available — try X" suggestion.
 */
export function nearestVersion(want: string, available: string[]): string | null {
  if (!available.length) return null;
  const sorted = sortVersionsDesc(available);
  if (sorted.includes(want)) return want;
  const pw = parseRelease(want);
  if (!pw) return sorted[0];
  const older = sorted.find((v) => compareMcVersions(v, want) < 0);
  const newer = [...sorted].reverse().find((v) => compareMcVersions(v, want) > 0);
  const sameLine = (v: string | undefined) => {
    const p = v ? parseRelease(v) : null;
    return !!p && p[0] === pw[0] && (pw[0] >= 20 || p[1] === pw[1]);
  };
  if (older && sameLine(older)) return older;
  if (newer && sameLine(newer)) return newer;
  return older ?? newer ?? sorted[0];
}

