/**
 * Vanilla (Mojang) — piston-meta version manifest v2.
 *
 *   GET https://piston-meta.mojang.com/mc/game/version_manifest_v2.json
 *       → { latest:{release,snapshot}, versions:[{id,type,url,time,releaseTime,sha1}] }
 *   GET <versions[].url>   (immutable — the URL embeds the json's sha1)
 *       → { downloads:{ server:{ sha1,size,url } }, javaVersion:{majorVersion} }
 *
 * Releases only (snapshots aren't orderable). Versions older than 1.2.5 have no
 * `downloads.server` at all and are recorded with zero builds (= not available).
 * Upstream publishes sha1 + size for every server jar; both are verified.
 *
 * Terms: the Minecraft EULA lets us run the server software for our customers;
 * we cache the UNMODIFIED jar for our own servers only (tokenised, unlisted URLs,
 * never a public download page) — see docs § "Minecraft server-software mirror".
 */
import type { Candidate, ProviderResult, TypeIndex } from "../types";
import type { McHttp } from "../http";

export const MOJANG_MANIFEST = "https://piston-meta.mojang.com/mc/game/version_manifest_v2.json";

export interface MojangManifest {
  latest: { release: string; snapshot: string };
  versions: { id: string; type: string; url: string; time: string; releaseTime: string; sha1: string }[];
}
export interface MojangVersionJson {
  id: string;
  javaVersion?: { majorVersion?: number };
  downloads?: { server?: { sha1: string; size: number; url: string } };
  releaseTime?: string;
}

/** Releases, newest first (Mojang already orders by releaseTime desc). */
export function parseMojangManifest(m: MojangManifest) {
  return m.versions
    .filter((v) => v.type === "release")
    .map((v) => ({ id: v.id, url: v.url, metaSha1: v.sha1, releasedAt: v.releaseTime }));
}

export function parseMojangVersion(id: string, v: MojangVersionJson): Candidate | null {
  const s = v.downloads?.server;
  if (!s || !/^[a-f0-9]{40}$/.test(s.sha1)) return null;
  return {
    type: "vanilla",
    mcVersion: id,
    build: id,
    channel: "stable",
    fileName: `minecraft_server.${id}.jar`,
    url: s.url,
    upstreamHash: { algo: "sha1", value: s.sha1 },
    size: s.size,
    publishedAt: v.releaseTime ?? null,
    extra: { javaMin: v.javaVersion?.majorVersion ?? 0 },
  };
}

export async function fetchVanilla(http: McHttp, prev: TypeIndex | null): Promise<ProviderResult> {
  const cond = prev?.http?.[MOJANG_MANIFEST];
  const top = await http.jsonCond<MojangManifest>(MOJANG_MANIFEST, cond);
  if (!top) return { source: "piston-meta-v2", versions: [], candidates: [], notModified: true };
  const releases = parseMojangManifest(top.data);
  const versions: ProviderResult["versions"] = [];
  const candidates: Candidate[] = [];
  for (const r of releases) {
    const p = prev?.versions[r.id];
    // Version JSONs are immutable (URL carries their sha1): reuse what we already parsed.
    const prevBuild = p?.builds.find((b) => b.build === r.id);
    if (p && (prevBuild?.extra?.metaSha1 === r.metaSha1 || (p.builds.length === 0 && p.releasedAt === r.releasedAt))) {
      versions.push({ mcVersion: r.id, channel: "stable", releasedAt: r.releasedAt, javaMin: p.javaMin ?? null });
      if (prevBuild) {
        candidates.push({
          type: "vanilla",
          mcVersion: r.id,
          build: r.id,
          channel: "stable",
          fileName: prevBuild.fileName,
          url: prevBuild.sourceUrl,
          upstreamHash: prevBuild.upstreamHash ?? null,
          size: prevBuild.size ?? null,
          publishedAt: prevBuild.publishedAt ?? null,
          extra: prevBuild.extra,
        });
      }
      continue;
    }
    const vj = await http.json<MojangVersionJson>(r.url);
    const c = parseMojangVersion(r.id, vj);
    versions.push({ mcVersion: r.id, channel: "stable", releasedAt: r.releasedAt, javaMin: vj.javaVersion?.majorVersion ?? null });
    if (c) {
      c.extra = { ...(c.extra ?? {}), metaSha1: r.metaSha1 };
      candidates.push(c);
    }
  }
  return {
    source: "piston-meta-v2",
    versions,
    candidates,
    http: { [MOJANG_MANIFEST]: { etag: top.etag, lastModified: top.lastModified } },
  };
}

