 * v2:
 *   GET /v2/projects/{p}                     → { versions:[string] }
 *   GET /v2/projects/{p}/versions/{v}/builds → { builds:[ { build, time, channel: default|experimental,
 *                                                 downloads:{ application:{ name, sha256 } } } ] }
 *   jar: /v2/projects/{p}/versions/{v}/builds/{b}/downloads/{name}
 *
 * NOTE (2026-10-01): both APIs were returning 503 for the whole day these
 * parsers were written, so the fixtures in test/fixtures/mcjars/paper-*.json
 * are CONSTRUCTED from the documented schema above, not recorded. Re-record
 * them (scripts/mcmirror.ts --record-fixtures) once PaperMC is back.
 *
 * PaperMC asks API consumers to send a descriptive User-Agent with contact
 * details and not to poll aggressively — we run every ~6 h, conditional GETs,
 * and only fetch a version's build list when its newest build id changed.
 */
import type { Candidate, Channel, ProviderResult, TypeIndex } from "../types";
import type { McHttp } from "../http";
import { sortVersionsDesc } from "../versions";

export type PaperProject = "paper" | "folia" | "velocity";
export const FILL_BASE = "https://fill.papermc.io";
export const PAPER_V2_BASE = "https://api.papermc.io";
/** Builds of metadata kept per version (downloads are decided by retention). */
export const META_BUILDS = 10;

export interface FillVersionsResponse {
  versions: { version: { id: string; support?: { status?: string }; java?: { version?: { minimum?: number } } }; builds: number[] }[];
}
export interface FillBuild {
  id: number;
  time?: string;
  channel: "ALPHA" | "BETA" | "STABLE" | "RECOMMENDED";
  downloads: Record<string, { name: string; checksums?: { sha256?: string }; size?: number; url: string }>;
}
export interface V2Project {
  versions: string[];
}
export interface V2Builds {
  builds: { build: number; time?: string; channel: "default" | "experimental"; downloads: { application?: { name: string; sha256: string } } }[];
}

const fillChannel = (c: string): Channel => (c === "STABLE" || c === "RECOMMENDED" ? "stable" : "experimental");

export function parseFillVersions(r: FillVersionsResponse) {
  return r.versions
    .filter((v) => v?.version?.id)
    .map((v) => ({
      id: v.version.id,
      builds: [...(v.builds ?? [])].sort((a, b) => b - a),
      javaMin: v.version.java?.version?.minimum ?? null,
      support: v.version.support?.status ?? null,
    }));
}

export function parseFillBuilds(type: PaperProject, mcVersion: string, builds: FillBuild[]): Candidate[] {
  return [...builds]
    .sort((a, b) => b.id - a.id)
    .slice(0, META_BUILDS)
    .flatMap((b) => {
      const d = b.downloads?.["server:default"];
      if (!d?.url || !d.name) return [];
      const sha = d.checksums?.sha256?.toLowerCase();
      return [
        {
          type,
          mcVersion,
          build: String(b.id),
          channel: fillChannel(b.channel),
          fileName: d.name,
          url: d.url,
          upstreamHash: sha && /^[a-f0-9]{64}$/.test(sha) ? { algo: "sha256" as const, value: sha } : null,
          size: d.size ?? null,
          publishedAt: b.time ?? null,
        },
      ];
    });
}

export function parseV2Builds(type: PaperProject, mcVersion: string, r: V2Builds): Candidate[] {
  return [...(r.builds ?? [])]
    .sort((a, b) => b.build - a.build)
    .slice(0, META_BUILDS)
    .flatMap((b) => {
      const app = b.downloads?.application;
      if (!app?.name) return [];
      const sha = app.sha256?.toLowerCase();
      return [
        {
          type,
          mcVersion,
          build: String(b.build),
          channel: (b.channel === "default" ? "stable" : "experimental") as Channel,
          fileName: app.name,
          url: `${PAPER_V2_BASE}/v2/projects/${type}/versions/${encodeURIComponent(mcVersion)}/builds/${b.build}/downloads/${encodeURIComponent(app.name)}`,
          upstreamHash: sha && /^[a-f0-9]{64}$/.test(sha) ? { algo: "sha256" as const, value: sha } : null,
          size: null,
          publishedAt: b.time ?? null,
        },
      ];
    });
}

/** Reuse the previous index's candidates for a version whose newest build hasn't changed. */
function reuse(prev: TypeIndex | null, v: string, newest: string): Candidate[] | null {
  const p = prev?.versions[v];
  if (!p || p.latestBuild !== newest) return null;
  return p.builds
    .filter((b) => b.channel !== "self-built")
    .map((b) => ({
      type: prev!.type,
      mcVersion: v,
      build: b.build,
      channel: b.channel,
      fileName: b.fileName,
      url: b.sourceUrl,
      upstreamHash: b.upstreamHash ?? null,
      size: b.size ?? null,
      publishedAt: b.publishedAt ?? null,
      extra: b.extra,
    }));
}

function versionChannel(cands: Candidate[]): Channel {
  return cands.some((c) => c.channel === "stable") ? "stable" : "experimental";
}

export async function fetchPaperV3(http: McHttp, project: PaperProject, prev: TypeIndex | null): Promise<ProviderResult> {
  const url = `${FILL_BASE}/v3/projects/${project}/versions`;
  const top = await http.jsonCond<FillVersionsResponse>(url, prev?.source === "fill-v3" ? prev?.http?.[url] : undefined);
  if (!top) return { source: "fill-v3", versions: [], candidates: [], notModified: true };
  const vers = parseFillVersions(top.data);
  const order = sortVersionsDesc(vers.map((v) => v.id));
  const byId = new Map(vers.map((v) => [v.id, v]));
  const versions: ProviderResult["versions"] = [];
  const candidates: Candidate[] = [];
  for (const id of order) {
    const v = byId.get(id)!;
    if (!v.builds.length) continue;
    const newest = String(v.builds[0]);
    let cands = prev?.source === "fill-v3" ? reuse(prev, id, newest) : null;
    if (!cands) {
      const builds = await http.json<FillBuild[]>(`${FILL_BASE}/v3/projects/${project}/versions/${encodeURIComponent(id)}/builds`);
      cands = parseFillBuilds(project, id, Array.isArray(builds) ? builds : []);
    }
    if (!cands.length) continue;
    versions.push({ mcVersion: id, channel: versionChannel(cands), javaMin: v.javaMin });
    candidates.push(...cands);
  }
  return { source: "fill-v3", versions, candidates, http: { [url]: { etag: top.etag, lastModified: top.lastModified } } };
}

export async function fetchPaperV2(http: McHttp, project: PaperProject, prev: TypeIndex | null): Promise<ProviderResult> {
  const url = `${PAPER_V2_BASE}/v2/projects/${project}`;
  const top = await http.json<V2Project>(url);
  const order = sortVersionsDesc(top.versions ?? []);
  const versions: ProviderResult["versions"] = [];
  const candidates: Candidate[] = [];
  for (const id of order) {
    const r = await http.json<V2Builds>(`${PAPER_V2_BASE}/v2/projects/${project}/versions/${encodeURIComponent(id)}/builds`);
    const cands = parseV2Builds(project, id, r);
    if (!cands.length) continue;
    versions.push({ mcVersion: id, channel: versionChannel(cands) });
    candidates.push(...cands);
  }
  void prev;
  return { source: "papermc-v2", versions, candidates };
}

/** v3 first; on any failure fall back to v2; if both fail, throw v3's error (the primary API). */
export async function fetchPaperProject(http: McHttp, project: PaperProject, prev: TypeIndex | null): Promise<ProviderResult> {
  try {
    return await fetchPaperV3(http, project, prev);
  } catch (e3) {
    try {
      return await fetchPaperV2(http, project, prev);
    } catch (e2) {
      const m3 = e3 instanceof Error ? e3.message : String(e3);
      const m2 = e2 instanceof Error ? e2.message : String(e2);
      throw new Error(`PaperMC fill v3 failed (${m3}); v2 fallback failed (${m2})`);
    }
  }
}

