/**
 * Purpur — https://api.purpurmc.org (MIT-licensed Paper fork).
 *
 *   GET /v2/purpur                → { project, metadata:{current}, versions:[oldest…newest] }
 *   GET /v2/purpur/{v}            → { builds:{ latest, all:[…] } }
 *   GET /v2/purpur/{v}/{b}        → { build, result:"SUCCESS", timestamp, md5 }
 *   GET /v2/purpur/{v}/{b}/download  (Content-Disposition: purpur-{v}-{b}.jar)
 *
 * Upstream publishes an md5 per build (only in the per-build JSON), so it is
 * fetched lazily at download time via `hashUrl.jsonField` — one extra small
 * request per file we actually mirror, none for metadata-only builds.
 */
import type { Candidate, ProviderResult, TypeIndex } from "../types";
import type { McHttp } from "../http";
import { compareBuilds, sortVersionsDesc } from "../versions";

export const PURPUR_BASE = "https://api.purpurmc.org";
const META_BUILDS = 10;

export interface PurpurProject {
  versions: string[];
}
export interface PurpurVersion {
  version: string;
  builds: { latest: string; all: string[] };
}

export function parsePurpurVersion(mcVersion: string, r: PurpurVersion): Candidate[] {
  const all = [...(r.builds?.all ?? [])].filter((b) => /^\d+$/.test(b)).sort((a, b) => compareBuilds(b, a));
  return all.slice(0, META_BUILDS).map((b) => ({
    type: "purpur" as const,
    mcVersion,
    build: b,
    channel: "stable" as const,
    fileName: `purpur-${mcVersion}-${b}.jar`,
    url: `${PURPUR_BASE}/v2/purpur/${encodeURIComponent(mcVersion)}/${b}/download`,
    hashUrl: [{ algo: "md5" as const, url: `${PURPUR_BASE}/v2/purpur/${encodeURIComponent(mcVersion)}/${b}`, jsonField: "md5" }],
    upstreamHash: null,
  }));
}

export async function fetchPurpur(http: McHttp, prev: TypeIndex | null): Promise<ProviderResult> {
  const url = `${PURPUR_BASE}/v2/purpur`;
  const top = await http.jsonCond<PurpurProject>(url, prev?.http?.[url]);
  const versionsList = top ? top.data.versions : prev?.order ?? [];
  const order = sortVersionsDesc(versionsList);
  const versions: ProviderResult["versions"] = [];
  const candidates: Candidate[] = [];
  for (const v of order) {
    // The per-version endpoint is the only place a new build shows up, so it is
    // always asked (conditionally) — ~40 tiny requests per run.
    const vurl = `${PURPUR_BASE}/v2/purpur/${encodeURIComponent(v)}`;
    const r = await http.jsonCond<PurpurVersion>(vurl, prev?.http?.[vurl]);
    let cands: Candidate[];
    if (!r) {
      const p = prev?.versions[v];
      cands = (p?.builds ?? []).map((b) => ({
        type: "purpur" as const,
        mcVersion: v,
        build: b.build,
        channel: b.channel,
        fileName: b.fileName,
        url: b.sourceUrl,
        upstreamHash: b.upstreamHash ?? null,
        hashUrl: [{ algo: "md5" as const, url: `${PURPUR_BASE}/v2/purpur/${encodeURIComponent(v)}/${b.build}`, jsonField: "md5" }],
      }));
    } else {
      cands = parsePurpurVersion(v, r.data);
      (prev ??= null);
      httpState[vurl] = { etag: r.etag, lastModified: r.lastModified };
    }
    if (!cands.length) continue;
    versions.push({ mcVersion: v, channel: "stable" });
    candidates.push(...cands);
  }
  const http_ = { ...httpState };
  if (top) http_[url] = { etag: top.etag, lastModified: top.lastModified };
  for (const k of Object.keys(httpState)) delete httpState[k];
  return { source: "purpur-v2", versions, candidates, http: { ...(prev?.http ?? {}), ...http_ } };
}

// Collected per fetch (module-scoped scratch, cleared at the end of each fetchPurpur).
const httpState: Record<string, { etag: string | null; lastModified: string | null }> = {};

