/**
 * Fabric — https://meta.fabricmc.net (Apache-2.0). We mirror the official
 * *server launcher* jar per game version × loader × installer:
 *
 *   GET /v2/versions/game       → [{ version, stable }]   newest first
 *   GET /v2/versions/loader     → [{ version, stable, … }] newest first
 *   GET /v2/versions/installer  → [{ version, stable, url }] newest first
 *   GET /v2/versions/loader/{game}/{loader}/{installer}/server/jar
 *       → fabric-server-mc.{game}-loader.{loader}-launcher.{installer}.jar
 *
 * The launcher jar is generated, so Fabric publishes NO checksum for it; we
 * record our own sha256 at mirror time and verify the file is a real jar
 * (ZIP magic). itzg uses it via FABRIC_LAUNCHER=/data/… (no meta.fabricmc.net
 * call at container start). On FIRST boot the launcher still downloads the
 * vanilla server jar + Fabric libraries (Mojang + maven.fabricmc.net — not
 * the same infrastructure as this meta API) into /data; restarts use that cache.
 *
 * Quilt (meta.quiltmc.org v3, Apache-2.0): mirrored as INSTALLER jars only
 * (game-version independent, sha256 published) under quilt/installer/ —
 * Quilt isn't an orderable server type yet; the game-version list is kept as
 * metadata so a future Quilt variant can validate combos.
 */
import type { Candidate, ProviderResult, TypeIndex } from "../types";
import type { McHttp } from "../http";

export const FABRIC_META = "https://meta.fabricmc.net";
export const QUILT_META = "https://meta.quiltmc.org";

export interface FabricGame {
  version: string;
  stable: boolean;
}
export interface FabricLoader {
  version: string;
  stable: boolean;
}
export interface FabricInstaller {
  version: string;
  stable: boolean;
  url?: string;
}

export function pickStable<T extends { stable: boolean }>(list: T[]): T | null {
  return list.find((x) => x.stable) ?? list[0] ?? null;
}

export function fabricLauncherCandidate(game: string, loader: string, installer: string): Candidate {
  return {
    type: "fabric",
    mcVersion: game,
    build: `${loader}+${installer}`,
    channel: "stable",
    fileName: `fabric-server-mc.${game}-loader.${loader}-launcher.${installer}.jar`,
    url: `${FABRIC_META}/v2/versions/loader/${encodeURIComponent(game)}/${encodeURIComponent(loader)}/${encodeURIComponent(installer)}/server/jar`,
    upstreamHash: null,
    extra: { loader, installer },
  };
}

export function parseFabric(games: FabricGame[], loaders: FabricLoader[], installers: FabricInstaller[]): ProviderResult {
  const loader = pickStable(loaders);
  const installer = pickStable(installers);
  const versions: ProviderResult["versions"] = [];
  const candidates: Candidate[] = [];
  if (!loader || !installer) return { source: "fabric-meta-v2", versions, candidates };
  for (const g of games) {
    if (!g.stable) continue; // snapshots/pre-releases aren't orderable
    versions.push({ mcVersion: g.version, channel: "stable" });
    candidates.push(fabricLauncherCandidate(g.version, loader.version, installer.version));
  }
  return { source: "fabric-meta-v2", versions, candidates };
}

export async function fetchFabric(http: McHttp, prev: TypeIndex | null): Promise<ProviderResult> {
  const gUrl = `${FABRIC_META}/v2/versions/game`;
  const [games, loaders, installers] = await Promise.all([
    http.json<FabricGame[]>(gUrl),
    http.json<FabricLoader[]>(`${FABRIC_META}/v2/versions/loader`),
