/**
 * Forge + NeoForge — installer jars from each project's OFFICIAL maven.
 *
 * Forge (LGPL-2.1, https://maven.minecraftforge.net):
 *   promotions  https://files.minecraftforge.net/net/minecraftforge/forge/promotions_slim.json
 *               → { promos: { "<mc>-recommended": "<forge>", "<mc>-latest": "<forge>" } }
 *   versions    https://maven.minecraftforge.net/net/minecraftforge/forge/maven-metadata.xml
 *               (maps a promo to its real maven coordinate — 1.7.10 builds carry a
 *               "-1.7.10" branch suffix, e.g. 1.7.10-10.13.4.1614-1.7.10)
 *   installer   …/forge/{coord}/forge-{coord}-installer.jar  (+ .sha256 / .sha1 sidecars)
 * We mirror recommended (stable) + latest (experimental, when different) per
 * MC version. Very old lines (≤1.5.1) have no installer — they 404 once and are
 * marked `gone`, so they're never offered.
 *
 * NeoForge (LGPL-2.1, https://maven.neoforged.net/releases):
 *   …/net/neoforged/neoforge/maven-metadata.xml → versions like 21.1.209, 26.1.2.5-beta
 *   installer …/neoforge/{v}/neoforge-{v}-installer.jar (+ .sha256 / .sha1)
 * MC version derived with versions.ts#neoforgeToMc. Newest non-beta = stable.
 *
 * itzg runs these via FORGE_INSTALLER / NEOFORGE_INSTALLER=/data/… — the image
 * reads the version straight out of the installer jar (mc-image-helper's
 * ProvidedInstallerResolver) and only re-runs it when that changes, so a
 * restart never contacts the Forge/NeoForge APIs. The installer's FIRST run
 * downloads libraries + the vanilla jar (Mojang + the loader's maven).
 */
import type { Candidate, Channel, ProviderResult, TypeIndex } from "../types";
import type { McHttp } from "../http";
import { compareBuilds, neoforgeToMc, sortVersionsDesc, parseRelease } from "../versions";

export const FORGE_PROMOS = "https://files.minecraftforge.net/net/minecraftforge/forge/promotions_slim.json";
export const FORGE_MAVEN = "https://maven.minecraftforge.net/net/minecraftforge/forge";
export const NEOFORGE_MAVEN = "https://maven.neoforged.net/releases/net/neoforged/neoforge";
const NEO_META_BUILDS = 6;

export function parseMavenVersions(xml: string): string[] {
  const out: string[] = [];
  const re = /<version>\s*([^<\s]+)\s*<\/version>/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(xml))) out.push(m[1]);
  return out;
}

const SAFE_COORD = /^[0-9][0-9A-Za-z._+-]{0,80}$/;

function forgeCandidate(mc: string, coord: string, forge: string, channel: Channel): Candidate {
  const file = `forge-${coord}-installer.jar`;
  const url = `${FORGE_MAVEN}/${coord}/${file}`;
  return {
    type: "forge",
    mcVersion: mc,
    build: forge,
    channel,
    fileName: file,
    url,
    upstreamHash: null,
    hashUrl: [
      { algo: "sha256", url: `${url}.sha256` },
      { algo: "sha1", url: `${url}.sha1` },
    ],
    extra: { coord },
  };
}

export function parseForge(promos: { promos: Record<string, string> }, mavenVersions: string[]): ProviderResult {
  const byMc = new Map<string, { rec?: string; latest?: string }>();
  for (const [k, v] of Object.entries(promos.promos ?? {})) {
    const m = /^(.+)-(recommended|latest)$/.exec(k);
    if (!m || !SAFE_COORD.test(v)) continue;
    const e = byMc.get(m[1]) ?? {};
    if (m[2] === "recommended") e.rec = v;
    else e.latest = v;
    byMc.set(m[1], e);
  }
  const mavenSet = new Set(mavenVersions);
  const coordFor = (mc: string, forge: string): string | null => {
    const plain = `${mc}-${forge}`;
    if (mavenSet.has(plain)) return plain;
    const branched = mavenVersions.find((v) => v.startsWith(`${plain}-`));
    return branched ?? null;
  };
  const versions: ProviderResult["versions"] = [];
  const candidates: Candidate[] = [];
  for (const mc of sortVersionsDesc([...byMc.keys()].filter((v) => parseRelease(v)))) {
    const e = byMc.get(mc)!;
    const cands: Candidate[] = [];
    if (e.rec) {
      const c = coordFor(mc, e.rec);
      if (c && SAFE_COORD.test(c)) cands.push(forgeCandidate(mc, c, e.rec, "stable"));
    }
    if (e.latest && e.latest !== e.rec) {
      const c = coordFor(mc, e.latest);
      // A line with no recommended build yet: "latest" is the best there is, flagged experimental.
      if (c && SAFE_COORD.test(c)) cands.push(forgeCandidate(mc, c, e.latest, e.rec ? "experimental" : "experimental"));
    }
    if (!cands.length) continue;
    cands.sort((a, b) => compareBuilds(b.build, a.build));
    versions.push({ mcVersion: mc, channel: e.rec ? "stable" : "experimental" });
    candidates.push(...cands);
  }
  return { source: "forge-promotions+maven", versions, candidates };
}

export async function fetchForge(http: McHttp, prev: TypeIndex | null): Promise<ProviderResult> {
  const promosUrl = FORGE_PROMOS;
  const metaUrl = `${FORGE_MAVEN}/maven-metadata.xml`;
  const promos = await http.jsonCond<{ promos: Record<string, string> }>(promosUrl, prev?.http?.[promosUrl]);
  if (!promos) return { source: "forge-promotions+maven", versions: [], candidates: [], notModified: true };
  const xml = await http.text(metaUrl);
  const r = parseForge(promos.data, parseMavenVersions(xml));
  r.http = { [promosUrl]: { etag: promos.etag, lastModified: promos.lastModified } };
  return r;
}

export function parseNeoForge(mavenVersions: string[]): ProviderResult {
  const byMc = new Map<string, string[]>();
  for (const v of mavenVersions) {
    if (!SAFE_COORD.test(v)) continue;
    const mc = neoforgeToMc(v);
    if (!mc) continue;
    const list = byMc.get(mc) ?? [];
    list.push(v);
    byMc.set(mc, list);
  }
  const versions: ProviderResult["versions"] = [];
  const candidates: Candidate[] = [];
  for (const mc of sortVersionsDesc([...byMc.keys()])) {
    const list = byMc.get(mc)!.sort((a, b) => compareBuilds(b, a));
    const hasStable = list.some((v) => !/-beta|-alpha/.test(v));
    // newest builds + always the newest stable one, even if it's older than the newest betas
    const keep = list.slice(0, NEO_META_BUILDS);
    const newestStable = list.find((v) => !/-beta|-alpha/.test(v));
    if (newestStable && !keep.includes(newestStable)) keep.push(newestStable);
    versions.push({ mcVersion: mc, channel: hasStable ? "stable" : "experimental" });
    for (const v of keep) {
      const file = `neoforge-${v}-installer.jar`;
      const url = `${NEOFORGE_MAVEN}/${v}/${file}`;
      candidates.push({
        type: "neoforge",
        mcVersion: mc,
        build: v,
        channel: /-beta|-alpha/.test(v) ? "experimental" : "stable",
        fileName: file,
        url,
        upstreamHash: null,
        hashUrl: [
          { algo: "sha256", url: `${url}.sha256` },
          { algo: "sha1", url: `${url}.sha1` },
        ],
      });
    }
  }
  return { source: "neoforged-maven", versions, candidates };
}

export async function fetchNeoForge(http: McHttp, prev: TypeIndex | null): Promise<ProviderResult> {
  const metaUrl = `${NEOFORGE_MAVEN}/maven-metadata.xml`;
  const r = await http.textCond(metaUrl, prev?.http?.[metaUrl]);
  if (!r) return { source: "neoforged-maven", versions: [], candidates: [], notModified: true };
  // Reposilite occasionally answers 200 with an HTML 404 page — treat as failure, not "no versions".
  if (!/<metadata>/.test(r.data)) throw new Error("NeoForge maven-metadata.xml was not XML (transient upstream error)");
  const out = parseNeoForge(parseMavenVersions(r.data));
  out.http = { [metaUrl]: { etag: r.etag, lastModified: r.lastModified } };
  return out;
}

