/**
 * SECOND-TIER fallback for Paper/Folia: build the server jar from the
 * project's own git source when PaperMC's download APIs (fill v3 + v2) are down
 * for a version/build we need (added after the 2026-10-01 outage — owner request).
 *
 * This module only PLANS a build. It never builds anything itself:
 *  - builds are on-demand / admin-triggered (scripts/mc-build-paper.ts), never on a timer;
 *  - they must run on a spare builder VM / CI-style helper, NEVER on the primary
 *    (memory/CPU-starved, serves production) — the emitted script refuses to run
 *    on a Proxmox host (`/etc/pve` present) unless --i-know is passed;
 *  - the resulting jar is imported into the mirror with `channel: "self-built"`
 *    and `provenance: "built-from-git@<commit>"` (lib/mcjars/store.ts#importLocalFile),
 *    flagged on /admin/mc-mirror, and only ever chosen by the pin planner when no
 *    official build is mirrored AND the official provider is currently failing,
 *    or when the owner pins it explicitly (lib/mcjars/plan.ts#pickBuild).
 *
 * Build recipe (read from the target ref's own README at plan time, because it
 * changes between branches — verified 2026-10-01):
 *   ver/26.x  : JDK 25, `./gradlew applyPatches` then `./gradlew createPaperclipJar`
 *   ver/1.21.x: JDK 21, `./gradlew applyPatches` then `./gradlew createMojmapBundlerJar`
 *   output    : paper-server/build/libs/
 * Folia's README has no compile section; the plan falls back to discovering a
 * create*PaperclipJar / create*BundlerJar task via `./gradlew tasks --all`
 * (UNVERIFIED for Folia — confirm on the first real build).
 *
 * Caveats (honest): a build needs an internet connection — Gradle pulls
 * Mojang's server jar and PaperMC's maven (repo.papermc.io), which is
 * separate infrastructure from fill.papermc.io but can share an outage. A
 * self-built jar is functionally what PaperMC would ship for that commit but
 * is NOT byte-identical to the official download (different build env), so
 * its sha256 is ours, not PaperMC's.
 */

export type GitProject = "paper" | "folia";

export const GIT_REPOS: Record<GitProject, string> = {
  paper: "https://github.com/PaperMC/Paper.git",
  folia: "https://github.com/PaperMC/Folia.git",
};

export interface BuildInstructions {
  jdk: number | null;
  tasks: string[];
  outputDir: string;
  /** true when parsed from the README; false = defaults/discovery. */
  fromReadme: boolean;
}

/** Parse "you need JDK 25" + "run `./gradlew applyPatches`, then `./gradlew createPaperclipJar`" + "in the `paper-server/build/libs` directory". */
export function parseBuildInstructions(readme: string): BuildInstructions {
  const jdk = /need\s+JDK\s+(\d{2})/i.exec(readme);
  const tasks: string[] = [];
  const re = /`\.\/gradlew\s+([A-Za-z][A-Za-z0-9]*)`/g;
  // Only look inside the "Compiling Jar From Source" section when present.
  const sec = /Compiling Jar From Source[\s\S]*?(?=\n How To|\nHow To \(|$)/i.exec(readme)?.[0] ?? "";
  let m: RegExpExecArray | null;
  while ((m = re.exec(sec))) if (!tasks.includes(m[1]) && m[1] !== "tasks") tasks.push(m[1]);
  const out = /find the compiled jar in the `([A-Za-z0-9_./-]+)` directory/i.exec(sec);
  const okTasks = tasks.length >= 1 && tasks.every((t) => /^[A-Za-z][A-Za-z0-9]{2,60}$/.test(t));
  return {
    jdk: jdk ? Number(jdk[1]) : null,
    tasks: okTasks ? tasks : [],
    outputDir: out && !out[1].includes("..") ? out[1] : "paper-server/build/libs",
    fromReadme: okTasks,
  };
}

/** The git ref to build for an MC version: a release tag "<v>" first, then branch "ver/<v>" / "ver/<v>.x", then main if main targets it. */
export function chooseRef(
  mcVersion: string,
  refs: { tags: string[]; branches: string[]; mainMcVersion?: string | null },
): string | null {
  if (refs.tags.includes(mcVersion)) return `refs/tags/${mcVersion}`;
  if (refs.branches.includes(`ver/${mcVersion}`)) return `ver/${mcVersion}`;
  const minor = mcVersion.split(".").slice(0, 2).join(".");
  if (refs.branches.includes(`ver/${mcVersion}.x`)) return `ver/${mcVersion}.x`;
  if (refs.branches.includes(`ver/${minor}.x`)) return `ver/${minor}.x`;
  if (refs.mainMcVersion === mcVersion) return "main";
  return null;
}

/** Default JDK when the README doesn't say: Paper's own policy (25 for 26.x, 21 for 1.20.5+, 17 below). */
export function defaultJdk(mcVersion: string): number {
  const [a, b, c] = mcVersion.split(".").map(Number);
  if (a >= 26) return 25;
  if (a === 1 && (b > 20 || (b === 20 && (c ?? 0) >= 5))) return 21;
  return 17;
}

export interface GitBuildPlan {
  project: GitProject;
  mcVersion: string;
  repo: string;
  ref: string;
  jdk: number;
  tasks: string[];
  outputDir: string;
  instructionsFromReadme: boolean;
  /** Self-contained bash for a BUILDER VM (docker + git required there). */
  script: string;
}

const SAFE_REF = /^(refs\/tags\/)?[A-Za-z0-9][A-Za-z0-9._/-]{0,80}$/;

export function buildPlan(project: GitProject, mcVersion: string, ref: string, ins: BuildInstructions): GitBuildPlan {
  if (!/^\d+(\.\d+){1,3}$/.test(mcVersion)) throw new Error("bad mcVersion");
  if (!SAFE_REF.test(ref) || ref.includes("..")) throw new Error("bad git ref");
  const jdk = ins.jdk ?? defaultJdk(mcVersion);
  if (![17, 21, 25].includes(jdk)) throw new Error(`unexpected JDK ${jdk}`);
  const repo = GIT_REPOS[project];
  const tasks = ins.tasks.length ? ins.tasks : [];
  const gradleSteps = tasks.length
    ? tasks.map((t) => `./gradlew --no-daemon ${t}`).join(" && ")
    : // Discovery fallback (Folia / unknown README): apply patches, then the first paperclip/bundler task Gradle knows.
      `(./gradlew --no-daemon applyAllPatches || ./gradlew --no-daemon applyPatches) && ` +
      `T=$(./gradlew --no-daemon -q tasks --all | grep -oE '^create(Mojmap)?(Paperclip|Bundler)Jar' | head -1) && [ -n "$T" ] && ./gradlew --no-daemon "$T"`;
  const branchArg = ref.startsWith("refs/tags/") ? ref.slice("refs/tags/".length) : ref;
  const script = [
    "#!/bin/bash",
    "# Nxeon mirror — self-build of " + project + " " + mcVersion + " (" + ref + "). Run on a BUILDER VM, never on the primary.",
    "set -euo pipefail",
    'if [ -d /etc/pve ] && [ "${1:-}" != "--i-know" ]; then echo "refusing: this looks like a Proxmox node (/etc/pve). Build on a spare VM." >&2; exit 3; fi',
    "W=$(mktemp -d /var/tmp/nxbuild.XXXXXX)",
    `git clone --depth 50 --branch '${branchArg}' '${repo}' "$W/src"`,
    'COMMIT=$(git -C "$W/src" rev-parse HEAD)',
    `docker run --rm -m 6g -v "$W/src":/src -w /src eclipse-temurin:${jdk}-jdk bash -lc 'git config --global user.email build@nxeon.local && git config --global user.name nxeon-build && ${gradleSteps.replace(/'/g, "'\\''")}'`,
    `JAR=$(ls -1S "$W/src/${ins.outputDir}"/*.jar | grep -viE 'sources|javadoc|dev' | head -1)`,
    '[ -f "$JAR" ] || { echo "no jar produced" >&2; exit 4; }',
    'SHA=$(sha256sum "$JAR" | cut -d" " -f1)',
    'echo "NXBUILD jar=$JAR commit=$COMMIT sha256=$SHA"',
    `echo "Next: copy the jar to the primary and run: npx tsx scripts/mc-build-paper.ts --import \\"<path>\\" --project ${project} --version ${mcVersion} --commit $COMMIT --sha256 $SHA"`,
  ].join("\n");
  return { project, mcVersion, repo, ref, jdk, tasks, outputDir: ins.outputDir, instructionsFromReadme: ins.fromReadme, script };
}

/** Network side (GitHub API + raw README) — used by scripts/mc-build-paper.ts only. */
export async function resolveGitBuildPlan(project: GitProject, mcVersion: string, fetchImpl: typeof fetch = fetch): Promise<GitBuildPlan> {
  const ownerRepo = project === "paper" ? "PaperMC/Paper" : "PaperMC/Folia";
  const h = { "User-Agent": "NxeonMcMirror/1.0 (+https://nxeon.cloud)", Accept: "application/vnd.github+json" };
  const j = async (u: string) => {
    const r = await fetchImpl(u, { headers: h, signal: AbortSignal.timeout(20_000) });
    if (!r.ok) throw new Error(`GitHub ${r.status} for ${u}`);
    return r.json();
  };
  const [tags, branches] = await Promise.all([
    j(`https://api.github.com/repos/${ownerRepo}/tags?per_page=100`) as Promise<{ name: string }[]>,
    j(`https://api.github.com/repos/${ownerRepo}/branches?per_page=100`) as Promise<{ name: string }[]>,
  ]);
  let mainMc: string | null = null;
  try {
    const gp = await (await fetchImpl(`https://raw.githubusercontent.com/${ownerRepo}/main/gradle.properties`, { headers: h })).text();
    mainMc = /^mcVersion=(.+)$/m.exec(gp)?.[1]?.trim() ?? null;
  } catch {
    /* optional */
  }
  const ref = chooseRef(mcVersion, { tags: tags.map((t) => t.name), branches: branches.map((b) => b.name), mainMcVersion: mainMc });
  if (!ref) throw new Error(`no ${project} tag/branch found for Minecraft ${mcVersion}`);
  const rawRef = ref.startsWith("refs/tags/") ? ref.slice(10) : ref;
  let readme = "";
  try {
    readme = await (await fetchImpl(`https://raw.githubusercontent.com/${ownerRepo}/${rawRef}/README.md`, { headers: h })).text();
  } catch {
    /* fall back to discovery */
  }
  return buildPlan(project, mcVersion, ref, parseBuildInstructions(readme));
}

