import type { McType, ProviderResult, TypeIndex } from "./types";
import type { McHttp } from "./http";
import { fetchVanilla } from "./providers/mojang";
import { fetchPaperProject } from "./providers/paper";
import { fetchPurpur } from "./providers/purpur";
import { fetchFabric, fetchQuilt } from "./providers/fabric";
import { fetchForge, fetchNeoForge } from "./providers/forge";
import { fetchBedrock } from "./providers/bedrock";

export interface ProviderDef {
  type: McType;
  label: string;
  /** Upstream terms note shown on the admin page. */
  terms: string;
