  const root = opts.root ?? mirrorRoot();
  if (!validSegment("version", opts.mcVersion) || !validSegment("file", opts.fileName) || !/^[A-Za-z0-9._+-]{1,60}$/.test(opts.build)) {
    return { ok: false, error: "bad version/file/build" };
  }
  const h = await hashFile(opts.srcPath);
  if (opts.expectSha256 && opts.expectSha256.toLowerCase() !== h.sha256) return { ok: false, error: "sha256 mismatch vs the builder's report" };
  const fh = await fs.open(opts.srcPath, "r");
  const head = Buffer.alloc(4);
  await fh.read(head, 0, 4, 0);
  await fh.close();
  if (!head.equals(ZIP_MAGIC)) return { ok: false, error: "not a jar" };
  await fs.mkdir(path.join(root, ".tmp"), { recursive: true, mode: 0o755 });
  const tmp = path.join(root, ".tmp", `${randomBytes(8).toString("hex")}.part`);
  await fs.copyFile(opts.srcPath, tmp);
  const r = await commitTmp(tmp, safeJoin(root, opts.type, opts.mcVersion, opts.fileName), h.sha256, h.size);
  if (!r.ok) return { ok: false, error: r.error };
