/**
 * On-disk mirror store.
 *
 *   <root>/manifest.json                     global summary (atomic write)
 *   <root>/<type>/index.json                 per-type index: versions, builds, sha256, size,
 *                                            source URL, fetchedAt, channel (atomic write)
 *   <root>/<type>/<mcVersion>/<file>         the artifact — immutable once written
 *   <root>/.tmp/                             in-flight downloads (same FS → atomic rename)
 *   <root>/.quarantine/                      files that failed a re-hash (kept for forensics)
 *
 * Invariants:
 *  - a file is written ONLY by rename from .tmp after its sha256 (and the
 *    upstream digest, when published) verified; it is never rewritten in place.
 *    If upstream later serves different bytes under the same name, the existing
 *    file is kept and the conflict is recorded ("immutable-conflict").
 *  - every path that leaves this module went through `safeJoin`, which only
 *    accepts allowlisted segments and re-checks containment after resolve().
 *  - index.json is the source of truth for "what is mirrored" — the serving
 *    route and the provisioning planner read it without needing the DB.
 */
import { createHash, randomBytes } from "node:crypto";
import { createReadStream, createWriteStream } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { Readable, Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import { mirrorRoot, tmpDir } from "./config";
import { HttpError, type McHttp } from "./http";
import type { Candidate, GlobalManifest, HashAlgo, IndexBuild, IndexVersion, McType, ProviderResult, TypeIndex } from "./types";
import { isMcType } from "./types";
import { compareBuilds, sortVersionsDesc } from "./versions";

export const VERSION_RE = /^[0-9A-Za-z][0-9A-Za-z._+-]{0,40}$/;
export const FILE_RE = /^[A-Za-z0-9][A-Za-z0-9._+-]{0,150}\.(jar|zip)$/;
export const SHA256_RE = /^[a-f0-9]{64}$/;
/** Hard per-file ceiling (Bedrock zips are ~100 MB; the largest Java jar today is ~70 MB). */
export const MAX_FILE_BYTES = 400 * 1024 * 1024;

export function validSegment(kind: "type" | "version" | "file", s: string): boolean {
  if (typeof s !== "string" || s.includes("..") || s.includes("/") || s.includes("\\") || s.includes("\0")) return false;
  if (kind === "type") return isMcType(s);
  if (kind === "version") return VERSION_RE.test(s);
  return FILE_RE.test(s);
}

/** Join under the mirror root, refusing anything that isn't an allowlisted segment or escapes the root. */
export function safeJoin(root: string, type: string, version?: string, file?: string): string {
  if (!validSegment("type", type)) throw new Error("bad type");
  if (version !== undefined && !validSegment("version", version)) throw new Error("bad version");
  if (file !== undefined && !validSegment("file", file)) throw new Error("bad file");
  const base = path.resolve(root);
  const parts = [base, type, ...(version !== undefined ? [version] : []), ...(file !== undefined ? [file] : [])];
  const abs = path.resolve(...parts);
  if (abs !== base && !abs.startsWith(base + path.sep)) throw new Error("path escapes mirror root");
  return abs;
}

// ---------------------------------------------------------------------------
// Atomic JSON I/O
// ---------------------------------------------------------------------------

export async function writeFileAtomic(file: string, data: string | Buffer): Promise<void> {
  const dir = path.dirname(file);
  await fs.mkdir(dir, { recursive: true, mode: 0o755 });
  const tmp = path.join(dir, `.${path.basename(file)}.${process.pid}.${randomBytes(4).toString("hex")}.tmp`);
  const fh = await fs.open(tmp, "w", 0o644);
  try {
    await fh.writeFile(data);
    await fh.sync();
  } finally {
    await fh.close();
  }
  await fs.rename(tmp, file);
}

export async function readJson<T>(file: string): Promise<T | null> {
  try {
    return JSON.parse(await fs.readFile(file, "utf8")) as T;
  } catch {
    return null;
  }
}

export function indexPath(root: string, type: McType): string {
  return path.join(safeJoin(root, type), "index.json");
}

export async function readIndex(type: McType, root = mirrorRoot()): Promise<TypeIndex | null> {
  const ix = await readJson<TypeIndex>(indexPath(root, type));
  return ix && ix.schema === 1 && ix.type === type && ix.versions ? ix : null;
}

export async function writeIndex(ix: TypeIndex, root = mirrorRoot()): Promise<void> {
  await writeFileAtomic(indexPath(root, ix.type), JSON.stringify(ix, null, 1));
}

// ---------------------------------------------------------------------------
// Merge provider metadata into the index (pure)
// ---------------------------------------------------------------------------

function toIndexBuild(c: Candidate, prev?: IndexBuild): IndexBuild {
  const same = prev && prev.fileName === c.fileName;
  return {
    build: c.build,
    channel: c.channel,
    fileName: c.fileName,
    sourceUrl: c.url,
    upstreamHash: c.upstreamHash ?? (same ? prev?.upstreamHash ?? null : null),
    size: c.size ?? (same ? prev?.size ?? null : null),
    publishedAt: c.publishedAt ?? (same ? prev?.publishedAt ?? null : null),
    extra: c.extra ?? (same ? prev?.extra : undefined),
    provenance: same ? prev?.provenance ?? "upstream" : "upstream",
    gone: same ? prev?.gone ?? false : false,
    sha256: same ? prev?.sha256 ?? null : null,
    mirrored: same ? !!prev?.mirrored : false,
    fetchedAt: same ? prev?.fetchedAt ?? null : null,
    verifiedAt: same ? prev?.verifiedAt ?? null : null,
    lastError: same ? prev?.lastError ?? null : null,
  };
}

/** Self-built builds sort after official ones; within a class, newest first. */
function sortBuilds(builds: IndexBuild[]): IndexBuild[] {
  return [...builds].sort((a, b) => {
    const sa = a.channel === "self-built" ? 1 : 0;
    const sb = b.channel === "self-built" ? 1 : 0;
    if (sa !== sb) return sa - sb;
    return compareBuilds(b.build, a.build);
  });
}

export function summarizeVersion(builds: IndexBuild[], channel: IndexVersion["channel"], extra?: Partial<IndexVersion>): IndexVersion {
  const sorted = sortBuilds(builds);
  const official = sorted.filter((b) => b.channel !== "self-built" && !b.gone);
  return {
    channel,
    latestBuild: official[0]?.build ?? null,
    latestStableBuild: official.find((b) => b.channel === "stable")?.build ?? null,
    builds: sorted,
    releasedAt: extra?.releasedAt ?? null,
    javaMin: extra?.javaMin ?? null,
  };
}

export function mergeIndex(type: McType, prev: TypeIndex | null, r: ProviderResult, now = new Date()): TypeIndex {
  if (r.notModified && prev) return { ...prev, http: { ...(prev.http ?? {}), ...(r.http ?? {}) } };
  const versions: Record<string, IndexVersion> = {};
  const byVersion = new Map<string, Candidate[]>();
  for (const c of r.candidates) {
    if (c.type !== type || !validSegment("version", c.mcVersion) || !validSegment("file", c.fileName)) continue;
    const l = byVersion.get(c.mcVersion) ?? [];
    if (!l.some((x) => x.build === c.build)) l.push(c);
    byVersion.set(c.mcVersion, l);
  }
  for (const v of r.versions) {
    if (!validSegment("version", v.mcVersion)) continue;
    const p = prev?.versions[v.mcVersion];
    const prevBuilds = new Map((p?.builds ?? []).map((b) => [b.build, b]));
    const cands = byVersion.get(v.mcVersion) ?? [];
    const builds = cands.map((c) => toIndexBuild(c, prevBuilds.get(c.build)));
    // Keep anything we hold on disk (or built ourselves) even if upstream stopped listing it.
    for (const pb of p?.builds ?? []) {
      if (!builds.some((b) => b.build === pb.build) && (pb.mirrored || pb.channel === "self-built")) builds.push(pb);
    }
    versions[v.mcVersion] = summarizeVersion(builds, v.channel, { releasedAt: v.releasedAt ?? p?.releasedAt, javaMin: v.javaMin ?? p?.javaMin });
  }
  // Versions upstream no longer lists but we still hold files for (e.g. older Bedrock releases).
  for (const [ver, p] of Object.entries(prev?.versions ?? {})) {
    if (versions[ver]) continue;
    const kept = p.builds.filter((b) => b.mirrored || b.channel === "self-built");
    if (kept.length) versions[ver] = summarizeVersion(kept, p.channel, p);
  }
  return {
    schema: 1,
    type,
    updatedAt: now.toISOString(),
    source: r.source,
    order: sortVersionsDesc(Object.keys(versions)),
    versions,
    http: { ...(prev?.http ?? {}), ...(r.http ?? {}) },
  };
}

// ---------------------------------------------------------------------------
// Retention (pure): what to download, what may be evicted
// ---------------------------------------------------------------------------

export interface InUse {
  type: McType;
  mcVersion: string;
  build?: string | null;
}

export interface RetentionOpts {
  keepHot: number;
  hotVersions: number;
  scope: "all" | "hot";
  inUse: InUse[];
  maxBytes: number;
  /** Bytes currently mirrored across ALL types (budget is global). */
  usedBytes: number;
  /** Estimate for builds with unknown size. */
  unknownSize?: number;
}

export interface RetentionPlan {
  download: { mcVersion: string; build: IndexBuild; priority: number }[];
  evict: { mcVersion: string; build: IndexBuild }[];
  skippedForBudget: number;
  hot: string[];
}

export function hotSet(ix: TypeIndex, opts: Pick<RetentionOpts, "hotVersions" | "inUse">): Set<string> {
  const hot = new Set<string>();
  for (const v of ix.order.filter((v) => ix.versions[v]?.channel === "stable").slice(0, opts.hotVersions)) hot.add(v);
  for (const u of opts.inUse) if (u.type === ix.type && ix.versions[u.mcVersion]) hot.add(u.mcVersion);
  return hot;
}

/** Builds a version should hold locally, newest first. */
export function wantedBuilds(ver: IndexVersion, isHot: boolean, keepHot: number, scope: "all" | "hot"): IndexBuild[] {
  const official = ver.builds.filter((b) => b.channel !== "self-built" && !b.gone);
  if (!isHot && scope === "hot") return [];
  const stable = official.filter((b) => b.channel === "stable");
  const pool = stable.length ? stable : official;
  if (!isHot) return pool.slice(0, 1);
  // Hot: newest N stable builds, plus the newest experimental one if it is newer than every stable (Forge "latest", NeoForge beta).
  const out = pool.slice(0, keepHot);
  const newestAny = official[0];
  if (newestAny && !out.includes(newestAny) && out.length < keepHot + 1) out.push(newestAny);
  return out;
}

export function planRetention(ix: TypeIndex, opts: RetentionOpts): RetentionPlan {
  const hot = hotSet(ix, opts);
  const inUseKey = new Set(opts.inUse.filter((u) => u.type === ix.type).map((u) => `${u.mcVersion}|${u.build ?? "*"}`));
  const isInUse = (v: string, b: IndexBuild) => inUseKey.has(`${v}|${b.build}`);
  const download: RetentionPlan["download"] = [];
  const evict: RetentionPlan["evict"] = [];
  ix.order.forEach((v, rank) => {
    const ver = ix.versions[v];
    if (!ver) return;
    const isHot = hot.has(v);
    const wanted = new Set(wantedBuilds(ver, isHot, opts.keepHot, opts.scope).map((b) => b.build));
    // In use with an unknown build ("*") → that version's latest stable is wanted.
    if (inUseKey.has(`${v}|*`) && (ver.latestStableBuild || ver.latestBuild)) wanted.add((ver.latestStableBuild ?? ver.latestBuild)!);
    for (const b of ver.builds) {
      const inUse = isInUse(v, b);
      if ((wanted.has(b.build) || inUse) && !b.mirrored && !b.gone && b.channel !== "self-built") {
        // priority: in use (0) > hot (1) > cold, newer versions first
        download.push({ mcVersion: v, build: b, priority: inUse ? 0 : isHot ? 1 : 2 + rank / 10_000 });
      } else if (b.mirrored && !wanted.has(b.build) && !inUse && b.channel !== "self-built") {
        evict.push({ mcVersion: v, build: b });
      }
    }
  });
  download.sort((a, b) => a.priority - b.priority);
  // Budget: never plan past maxBytes (eviction of unwanted files is counted as freed space).
  const freed = evict.reduce((s, e) => s + (e.build.size ?? 0), 0);
  let budget = opts.maxBytes - opts.usedBytes + freed;
  const est = opts.unknownSize ?? 60 * 1024 * 1024;
  const kept: RetentionPlan["download"] = [];
  let skipped = 0;
  for (const d of download) {
    const sz = d.build.size ?? est;
    if (d.priority === 0 || sz <= budget) {
      kept.push(d);
      budget -= sz;
    } else skipped++;
  }
  return { download: kept, evict, skippedForBudget: skipped, hot: [...hot] };
}

// ---------------------------------------------------------------------------
// Download + verify (I/O)
// ---------------------------------------------------------------------------

export type DownloadOutcome =
  | { ok: true; sha256: string; size: number; reused?: boolean }
  | { ok: false; gone?: boolean; error: string };

const ZIP_MAGIC = Buffer.from([0x50, 0x4b, 0x03, 0x04]);

async function fetchHash(http: McHttp, h: { algo: HashAlgo; url: string; jsonField?: string }): Promise<string | null> {
  try {
    if (h.jsonField) {
      const j = await http.json<Record<string, unknown>>(h.url);
      const v = j?.[h.jsonField];
      return typeof v === "string" ? v.trim().toLowerCase() : null;
    }
    const t = await http.text(h.url, { maxRetries: 2 });
    const tok = t.trim().split(/\s+/)[0]?.toLowerCase() ?? "";
    return /^[a-f0-9]{32,128}$/.test(tok) ? tok : null;
  } catch (e) {
    if (e instanceof HttpError && (e.status === 404 || e.status === 410)) return null;
    throw e;
  }
}

/** Hash a local file with sha256 (+ optional second algo). */
export async function hashFile(file: string, algo2?: HashAlgo): Promise<{ sha256: string; other?: string; size: number }> {
  const h = createHash("sha256");
  const h2 = algo2 && algo2 !== "sha256" ? createHash(algo2) : null;
  let size = 0;
  for await (const chunk of createReadStream(file)) {
    const b = chunk as Buffer;
    size += b.length;
    h.update(b);
    h2?.update(b);
  }
  const sha256 = h.digest("hex");
  return { sha256, other: h2 ? h2.digest("hex") : algo2 === "sha256" ? sha256 : undefined, size };
}

export async function downloadBuild(
  http: McHttp,
  type: McType,
  mcVersion: string,
  b: IndexBuild,
  opts: { root?: string; hashUrl?: Candidate["hashUrl"] } = {},
): Promise<DownloadOutcome> {
  const root = opts.root ?? mirrorRoot();
  const dest = safeJoin(root, type, mcVersion, b.fileName);
  await fs.mkdir(path.join(root, ".tmp"), { recursive: true, mode: 0o755 });
  const tmp = path.join(root, ".tmp", `${randomBytes(8).toString("hex")}.part`);
  let expect = b.upstreamHash ?? null;
  try {
    if (!expect && opts.hashUrl?.length) {
      for (const h of opts.hashUrl) {
        const v = await fetchHash(http, h);
        if (v) {
          expect = { algo: h.algo, value: v };
          break;
        }
      }
    }
    const res = await http.request(b.sourceUrl, { headers: { Accept: "*/*" }, timeoutMs: 15 * 60_000 });
    if (res.status === 404 || res.status === 410) {
      try { await res.arrayBuffer(); } catch { /* drain */ }
      return { ok: false, gone: true, error: `HTTP ${res.status}` };
    }
    if (!res.ok || !res.body) throw new HttpError(res.status, b.sourceUrl);
    const declared = Number(res.headers.get("content-length") ?? 0);
    if (declared > MAX_FILE_BYTES) throw new Error(`file too large (${declared} bytes)`);
    const h256 = createHash("sha256");
    const h2 = expect && expect.algo !== "sha256" ? createHash(expect.algo) : null;
    let size = 0;
    let head = Buffer.alloc(0);
    const meter = new Transform({
      transform(chunk: Buffer, _enc, cb) {
        size += chunk.length;
        if (size > MAX_FILE_BYTES) return cb(new Error("file exceeds size cap while streaming"));
        if (head.length < 4) head = Buffer.concat([head, chunk.subarray(0, 4 - head.length)]);
        h256.update(chunk);
        h2?.update(chunk);
        cb(null, chunk);
      },
    });
    await pipeline(Readable.fromWeb(res.body as never), meter, createWriteStream(tmp, { mode: 0o644 }));
    const sha256 = h256.digest("hex");
    if (!head.equals(ZIP_MAGIC)) throw new Error("downloaded file is not a jar/zip (bad magic)");
    if (b.size && size !== b.size) throw new Error(`size mismatch: got ${size}, upstream says ${b.size}`);
    if (declared && size !== declared) throw new Error(`truncated: got ${size} of ${declared} bytes`);
    if (expect) {
      const got = expect.algo === "sha256" ? sha256 : h2!.digest("hex");
      if (got !== expect.value.toLowerCase()) throw new Error(`${expect.algo} mismatch vs upstream digest`);
    }
    return await commitTmp(tmp, dest, sha256, size);
  } catch (e) {
    await fs.rm(tmp, { force: true }).catch(() => {});
    if (e instanceof HttpError && (e.status === 404 || e.status === 410)) return { ok: false, gone: true, error: `HTTP ${e.status}` };
    return { ok: false, error: (e instanceof Error ? e.message : String(e)).slice(0, 300) };
  }
}

/** Move a verified tmp file into place. Immutable: an existing different file is never replaced. */
export async function commitTmp(tmp: string, dest: string, sha256: string, size: number): Promise<DownloadOutcome> {
  await fs.mkdir(path.dirname(dest), { recursive: true, mode: 0o755 });
  try {
    const st = await fs.stat(dest);
    if (st.isFile()) {
      const existing = await hashFile(dest);
      await fs.rm(tmp, { force: true });
      if (existing.sha256 === sha256) return { ok: true, sha256, size, reused: true };
      return { ok: false, error: "immutable-conflict: a different file with this name is already mirrored (kept the existing one)" };
    }
  } catch {
    /* dest absent — normal */
  }
  await fs.chmod(tmp, 0o644).catch(() => {});
  await fs.rename(tmp, dest);
  return { ok: true, sha256, size };
}

/** Re-hash a mirrored file; quarantine it if it no longer matches. Returns true when healthy. */
export async function verifyBuild(type: McType, mcVersion: string, b: IndexBuild, root = mirrorRoot()): Promise<boolean> {
  const file = safeJoin(root, type, mcVersion, b.fileName);
  try {
    const h = await hashFile(file);
    if (b.sha256 && h.sha256 === b.sha256 && (!b.size || b.size === h.size)) return true;
  } catch {
    return false; // missing
  }
  const q = path.join(root, ".quarantine");
  await fs.mkdir(q, { recursive: true, mode: 0o755 }).catch(() => {});
  await fs.rename(file, path.join(q, `${type}__${mcVersion}__${b.fileName}.${Date.now()}`)).catch(() => {});
  return false;
}

export async function evictBuild(type: McType, mcVersion: string, b: IndexBuild, root = mirrorRoot()): Promise<void> {
  await fs.rm(safeJoin(root, type, mcVersion, b.fileName), { force: true });
  // drop the version dir if now empty (best-effort)
  await fs.rmdir(safeJoin(root, type, mcVersion)).catch(() => {});
}

/** Remove .tmp leftovers older than an hour (crashed runs). */
export async function cleanTmp(root = mirrorRoot(), olderThanMs = 3600_000): Promise<number> {
  let n = 0;
  try {
    for (const f of await fs.readdir(path.join(root, ".tmp"))) {
      const p = path.join(root, ".tmp", f);
      const st = await fs.stat(p).catch(() => null);
      if (st && Date.now() - st.mtimeMs > olderThanMs) {
        await fs.rm(p, { force: true });
        n++;
      }
    }
  } catch {
    /* no tmp dir */
  }
  return n;
}

/**
 * Import a jar produced outside the API path (Paper/Folia self-build) into the
 * mirror. Flagged `channel: "self-built"`, `provenance: built-from-git@<commit>`.
 */
export async function importLocalFile(opts: {
  type: McType;
  mcVersion: string;
  build: string;
  fileName: string;
  srcPath: string;
  provenance: string;
  expectSha256?: string;
  root?: string;
}): Promise<{ ok: true; sha256: string; size: number } | { ok: false; error: string }> {
  const root = opts.root ?? mirrorRoot();
  if (!validSegment("version", opts.mcVersion) || !validSegment("file", opts.fileName) || !/^[A-Za-z0-9._+-]{1,60}$/.test(opts.build)) {
    return { ok: false, error: "bad version/file/build" };
  }
  const h = await hashFile(opts.srcPath);
  if (opts.expectSha256 && opts.expectSha256.toLowerCase() !== h.sha256) return { ok: false, error: "sha256 mismatch vs the builder's report" };
  const fh = await fs.open(opts.srcPath, "r");
  const head = Buffer.alloc(4);
  await fh.read(head, 0, 4, 0);
  await fh.close();
  if (!head.equals(ZIP_MAGIC)) return { ok: false, error: "not a jar" };
  await fs.mkdir(path.join(root, ".tmp"), { recursive: true, mode: 0o755 });
  const tmp = path.join(root, ".tmp", `${randomBytes(8).toString("hex")}.part`);
  await fs.copyFile(opts.srcPath, tmp);
  const r = await commitTmp(tmp, safeJoin(root, opts.type, opts.mcVersion, opts.fileName), h.sha256, h.size);
  if (!r.ok) return { ok: false, error: r.error };
  const prev = (await readIndex(opts.type, root)) ?? { schema: 1 as const, type: opts.type, updatedAt: new Date().toISOString(), source: "self-built", order: [], versions: {} };
  const ver = prev.versions[opts.mcVersion];
  const builds = (ver?.builds ?? []).filter((b) => b.build !== opts.build);
  builds.push({
    build: opts.build,
    channel: "self-built",
    fileName: opts.fileName,
    sourceUrl: opts.provenance,
    provenance: opts.provenance,
    sha256: h.sha256,
    size: h.size,
    mirrored: true,
    fetchedAt: new Date().toISOString(),
    verifiedAt: new Date().toISOString(),
  });
  prev.versions[opts.mcVersion] = summarizeVersion(builds, ver?.channel ?? "stable", ver);
  prev.order = sortVersionsDesc(Object.keys(prev.versions));
  prev.updatedAt = new Date().toISOString();
  await writeIndex(prev, root);
  return { ok: true, sha256: h.sha256, size: h.size };
}

// ---------------------------------------------------------------------------
// Manifest + usage
// ---------------------------------------------------------------------------

export function mirroredBytes(ix: TypeIndex | null): { files: number; bytes: number } {
  let files = 0;
  let bytes = 0;
  for (const v of Object.values(ix?.versions ?? {})) {
    for (const b of v.builds) {
      if (b.mirrored) {
        files++;
        bytes += b.size ?? 0;
      }
    }
  }
  return { files, bytes };
}

export async function writeManifest(indexes: TypeIndex[], root = mirrorRoot()): Promise<GlobalManifest> {
  const prev = await readJson<GlobalManifest>(path.join(root, "manifest.json"));
  const types: GlobalManifest["types"] = { ...(prev?.types ?? {}) };
  for (const ix of indexes) {
    const u = mirroredBytes(ix);
    const newest = ix.order.find((v) => ix.versions[v]?.channel === "stable") ?? ix.order[0] ?? null;
    types[ix.type] = {
      updatedAt: ix.updatedAt,
      versions: ix.order.length,
      mirroredFiles: u.files,
      mirroredBytes: u.bytes,
      newest,
      newestBuild: newest ? ix.versions[newest]?.latestStableBuild ?? ix.versions[newest]?.latestBuild ?? null : null,
    };
  }
  const m: GlobalManifest = {
    schema: 1,
    updatedAt: new Date().toISOString(),
    types,
    totalBytes: Object.values(types).reduce((s, t) => s + t.mirroredBytes, 0),
  };
  await writeFileAtomic(path.join(root, "manifest.json"), JSON.stringify(m, null, 1));
  return m;
}

export async function readManifest(root = mirrorRoot()): Promise<GlobalManifest | null> {
  return readJson<GlobalManifest>(path.join(root, "manifest.json"));
}

