/**
 * One provider pass — DB-free so it can be exercised end-to-end against a
 * temp directory (scripts/mcmirror.ts --root /tmp/x) and in tests.
 *
 *   1. drop crashed .tmp leftovers
 *   2. fetch upstream metadata (conditional) → merge into index.json
 *   3. plan retention → evict unwanted files, download wanted ones
 *      (bounded per run; index.json rewritten every few files → resumable)
 *   4. re-hash a few of the oldest-verified files (corruption detection)
 */
import { mirrorRoot } from "./config";
import { McHttp } from "./http";
import type { ProviderDef } from "./registry";
import {
  cleanTmp,
  downloadBuild,
  evictBuild,
  mergeIndex,
  planRetention,
  readIndex,
  summarizeVersion,
  verifyBuild,
  writeIndex,
  type InUse,
} from "./store";
import type { TypeIndex } from "./types";

export interface SyncStats {
  type: string;
  notModified: boolean;
  metadataError: string | null;
  versions: number;
  downloaded: number;
  downloadedBytes: number;
  failed: number;
  gone: number;
  evicted: number;
  verified: number;
  corrupt: number;
  backlog: number;
  skippedForBudget: number;
  errors: string[];
  source: string | null;
}

export interface SyncOpts {
  root?: string;
  inUse: InUse[];
  usedBytesOtherTypes: number;
  maxBytes: number;
  keepHot: number;
  hotVersions: number;
  scope: "all" | "hot";
  /** Override per-run download cap (e.g. 0 = metadata only). */
  maxDownloads?: number;
  verifyPerRun?: number;
  fetchImpl?: typeof fetch;
  log?: (msg: string) => void;
  now?: () => number;
}

export async function syncProvider(def: ProviderDef, opts: SyncOpts): Promise<{ stats: SyncStats; index: TypeIndex | null }> {
  const root = opts.root ?? mirrorRoot();
  const log = opts.log ?? (() => {});
  const now = opts.now ?? Date.now;
  const deadline = now() + def.timeoutMs;
  const http = new McHttp({ ratePerMin: def.ratePerMin, fetchImpl: opts.fetchImpl, deadline });
  const stats: SyncStats = {
    type: def.type,
    notModified: false,
    metadataError: null,
    versions: 0,
    downloaded: 0,
    downloadedBytes: 0,
    failed: 0,
    gone: 0,
    evicted: 0,
    verified: 0,
    corrupt: 0,
    backlog: 0,
    skippedForBudget: 0,
    errors: [],
    source: null,
  };
  await cleanTmp(root);
  const prev = await readIndex(def.type, root);
  let ix: TypeIndex | null = prev;
  try {
    const r = await def.fetch(http, prev);
    stats.notModified = !!r.notModified;
    stats.source = r.source;
    if (!r.notModified && r.versions.length === 0) throw new Error("upstream returned no versions (refusing to wipe the index)");
    ix = mergeIndex(def.type, prev, r);
    await writeIndex(ix, root);
  } catch (e) {
    stats.metadataError = (e instanceof Error ? e.message : String(e)).slice(0, 500);
    log(`[mcmirror] ${def.type}: metadata failed: ${stats.metadataError}`);
  }
  if (!ix) return { stats, index: null };
  stats.versions = ix.order.length;

  const plan = planRetention(ix, {
    keepHot: opts.keepHot,
    hotVersions: opts.hotVersions,
    scope: opts.scope,
    inUse: opts.inUse,
    maxBytes: opts.maxBytes,
    usedBytes: opts.usedBytesOtherTypes + sumMirrored(ix),
  });
  stats.skippedForBudget = plan.skippedForBudget;

  // Evict first (frees budget). Never touches in-use / wanted / self-built (planRetention guarantees it).
  if (!stats.metadataError) {
    for (const e of plan.evict) {
      await evictBuild(def.type, e.mcVersion, e.build, root);
      e.build.mirrored = false;
      e.build.sha256 = e.build.sha256 ?? null;
      stats.evicted++;
    }
  }

  // Downloads only when metadata is fresh (an upstream that can't answer its API won't serve files either).
  const cap = opts.maxDownloads ?? def.maxDownloadsPerRun;
  let sinceWrite = 0;
  if (!stats.metadataError) {
    for (const d of plan.download) {
      if (stats.downloaded + stats.failed >= cap || now() > deadline) {
        stats.backlog++;
        continue;
      }
      const out = await downloadBuild(http, def.type, d.mcVersion, d.build, { root });
      if (out.ok) {
        d.build.mirrored = true;
        d.build.sha256 = out.sha256;
        d.build.size = out.size;
        d.build.fetchedAt = new Date(now()).toISOString();
        d.build.verifiedAt = d.build.fetchedAt;
        d.build.lastError = null;
        stats.downloaded++;
        stats.downloadedBytes += out.reused ? 0 : out.size;
        log(`[mcmirror] ${def.type} ${d.mcVersion} ${d.build.build}: mirrored ${out.size} B`);
      } else {
        d.build.lastError = out.error;
        if (out.gone) {
          d.build.gone = true;
          stats.gone++;
        } else {
          stats.failed++;
          stats.errors.push(`${d.mcVersion}/${d.build.build}: ${out.error}`);
        }
      }
      if (++sinceWrite >= 5) {
        sinceWrite = 0;
        await writeIndex(refresh(ix), root);
      }
    }
  }

  // Corruption detection: re-hash the N least-recently verified files.
  const verifyN = opts.verifyPerRun ?? 4;
  const mirrored = Object.entries(ix.versions)
    .flatMap(([v, ver]) => ver.builds.filter((b) => b.mirrored).map((b) => ({ v, b })))
    .sort((a, b) => (a.b.verifiedAt ?? "").localeCompare(b.b.verifiedAt ?? ""))
    .slice(0, verifyN);
  for (const { v, b } of mirrored) {
    if (b.verifiedAt && now() - Date.parse(b.verifiedAt) < 24 * 3600_000) continue;
    const ok = await verifyBuild(def.type, v, b, root);
    stats.verified++;
    if (ok) b.verifiedAt = new Date(now()).toISOString();
    else {
      b.mirrored = false;
      b.lastError = "integrity check failed — file quarantined, will re-download";
      stats.corrupt++;
      stats.errors.push(`${v}/${b.build}: corrupt (quarantined)`);
    }
  }
  ix = refresh(ix);
  await writeIndex(ix, root);
  return { stats, index: ix };
}

function refresh(ix: TypeIndex): TypeIndex {
  for (const [v, ver] of Object.entries(ix.versions)) ix.versions[v] = summarizeVersion(ver.builds, ver.channel, ver);
  ix.updatedAt = new Date().toISOString();
  return ix;
}

export function sumMirrored(ix: TypeIndex | null): number {
  let n = 0;
  for (const v of Object.values(ix?.versions ?? {})) for (const b of v.builds) if (b.mirrored) n += b.size ?? 0;
  return n;
}

