cd /opt/nxeon-wt-mcmirror && cat >> prisma/schema.prisma <<'EOF'

// ---------------------------------------------------------------------------
// Minecraft server-software mirror (lib/mcjars, worker/mcmirror.ts,
// /admin/mc-mirror). Additive only. The on-disk index.json under the mirror
// root is the source of truth for WHAT is mirrored; these tables hold the
// scheduler state, run history and which exact jar each server is pinned to.
// ---------------------------------------------------------------------------

/// One row per mirrored server-software type ("vanilla", "paper", …).
model McMirrorProvider {
  key                 String    @id
  enabled             Boolean   @default(true)
  paused              Boolean   @default(false)
  runRequested        Boolean   @default(false)
  /// Lease for the overlap guard: a run holds it until done (or it expires after a crash).
  leaseUntil          DateTime?
  nextRunAt           DateTime  @default(now())
  lastRunAt           DateTime?
  lastOkAt            DateTime?
  lastError           String?
  /// First failure of the current failure streak (cleared on success) — drives the >24 h alert.
  failingSince        DateTime?
  consecutiveFailures Int       @default(0)
  lastAlertAt         DateTime?
  lastStats           Json?
  updatedAt           DateTime  @updatedAt
}

model McMirrorRun {
  id         String    @id @default(cuid())
  type       String
  /// timer | run-now | cli
  trigger    String
  /// running | ok | partial | error
  status     String    @default("running")
  startedAt  DateTime  @default(now())
  finishedAt DateTime?
  stats      Json?
  error      String?

  @@index([type, startedAt])
