/**
 * Scheduler + run recording for the mirror (DB-aware). Called by the worker
 * (worker/mcmirror.ts, fire-and-forget, overlap-guarded) and by
 * scripts/mcmirror.ts. The web app never calls this — admin "Run now" only
 * flips `runRequested`; the worker does the upstream I/O.
 */
import { db } from "../db";
import { datasetUsage, hotVersionCount, keepBuildsHot, mirrorMaxBytes, mirrorReady, mirrorRoot, versionScope } from "./config";
import { PROVIDERS, providerFor, type ProviderDef } from "./registry";
import { readIndex, writeManifest, type InUse } from "./store";
import { syncProvider, sumMirrored, type SyncStats } from "./sync";
import { isMcType, type McType, type TypeIndex } from "./types";

export const RUN_INTERVAL_MS = 6 * 3600_000;
/** When a run left downloads behind (per-run cap), come back sooner. */
export const BACKLOG_INTERVAL_MS = 20 * 60_000;
export const LEASE_MS = 45 * 60_000;
export const ALERT_AFTER_MS = 24 * 3600_000;
export const QUOTA_ALERT_PCT = 90;

/** Exponential backoff after failures: 15 min, 30, 60, 120… capped at the normal 6 h interval. */
export function backoffAfterFailure(consecutive: number): number {
  return Math.min(RUN_INTERVAL_MS, 15 * 60_000 * 2 ** Math.max(0, consecutive - 1));
}

export async function ensureProviderRows(): Promise<void> {
  for (const p of PROVIDERS) {
    await db.mcMirrorProvider.upsert({ where: { key: p.type }, create: { key: p.type }, update: {} });
  }
}

/** Map an orderable variant id to a mirror type (1:1 today). */
export function variantType(variant: string | null | undefined): McType {
  const v = (variant ?? "vanilla").toLowerCase();
  return isMcType(v) ? v : "vanilla";
}

/** Every (type, version[, build]) a live server uses — never evicted, always "hot". */
export async function inUseFromDb(): Promise<InUse[]> {
  const out: InUse[] = [];
  const pins = await db.mcJarPin.findMany({ where: { state: { in: ["PLANNED", "ACTIVE"] } }, select: { type: true, mcVersion: true, build: true } });
  for (const p of pins) if (isMcType(p.type)) out.push({ type: p.type, mcVersion: p.mcVersion, build: p.build });
  const servers = await db.server.findMany({
    where: { status: { notIn: ["DELETING"] }, OR: [{ osTemplate: { family: "minecraft" } }, { gamePlan: { gameFamily: "minecraft" } }] },
    select: { gameVariant: true, gameConfig: true },
  });
  for (const s of servers) {
    const v = (s.gameConfig as Record<string, unknown> | null)?.VERSION;
    if (typeof v === "string" && v !== "LATEST") out.push({ type: variantType(s.gameVariant), mcVersion: v, build: null });
  }
  return out;
}

async function usedBytesExcept(type: McType, root: string): Promise<number> {
  let n = 0;
  for (const p of PROVIDERS) if (p.type !== type) n += sumMirrored(await readIndex(p.type, root));
  return n;
}

async function alert(action: string, detail: string): Promise<void> {
  // db.auditLog directly: recordAudit() reads request cookies, which the worker doesn't have.
  try {
    await db.auditLog.create({ data: { userId: null, action, detail } });
  } catch (e) {
    console.error("[mcmirror] audit write failed", e);
  }
}

export interface RunResult {
  type: McType;
  status: "ok" | "partial" | "error" | "skipped";
  stats?: SyncStats;
  error?: string;
}

/** Run one provider now (lease-guarded). Returns null if another run holds the lease. */
export async function runProvider(def: ProviderDef, trigger: "timer" | "run-now" | "cli", opts: { maxDownloads?: number; fetchImpl?: typeof fetch } = {}): Promise<RunResult | null> {
  const now = new Date();
  const claimed = await db.mcMirrorProvider.updateMany({
    where: { key: def.type, OR: [{ leaseUntil: null }, { leaseUntil: { lt: now } }] },
    data: { leaseUntil: new Date(now.getTime() + LEASE_MS), runRequested: false, lastRunAt: now },
  });
  if (claimed.count === 0) return null;
  const run = await db.mcMirrorRun.create({ data: { type: def.type, trigger } });
  const root = mirrorRoot();
  let result: RunResult;
  try {
    const { stats, index } = await syncProvider(def, {
      root,
      inUse: await inUseFromDb(),
      usedBytesOtherTypes: await usedBytesExcept(def.type, root),
      maxBytes: mirrorMaxBytes(),
      keepHot: keepBuildsHot(),
      hotVersions: hotVersionCount(),
      scope: versionScope(),
      maxDownloads: opts.maxDownloads,
      fetchImpl: opts.fetchImpl,
      log: (m) => console.log(m),
    });
    if (index) await writeManifest([index], root).catch(() => {});
    const status: RunResult["status"] = stats.metadataError ? "error" : stats.failed || stats.corrupt ? "partial" : "ok";
    result = { type: def.type, status, stats, error: stats.metadataError ?? undefined };
  } catch (e) {
    result = { type: def.type, status: "error", error: (e instanceof Error ? e.message : String(e)).slice(0, 500) };
  }
  await recordOutcome(def, run.id, result, trigger);
  return result;
}

async function recordOutcome(def: ProviderDef, runId: string, r: RunResult, trigger: string): Promise<void> {
  const row = await db.mcMirrorProvider.findUnique({ where: { key: def.type } });
  const now = new Date();
  const failed = r.status === "error";
  const consecutive = failed ? (row?.consecutiveFailures ?? 0) + 1 : 0;
  const failingSince = failed ? row?.failingSince ?? now : null;
  const backlog = (r.stats?.backlog ?? 0) > 0;
  const nextRunAt = new Date(now.getTime() + (failed ? backoffAfterFailure(consecutive) : backlog ? BACKLOG_INTERVAL_MS : RUN_INTERVAL_MS));
  let lastAlertAt = row?.lastAlertAt ?? null;
  if (failed && failingSince && now.getTime() - failingSince.getTime() > ALERT_AFTER_MS && (!lastAlertAt || now.getTime() - lastAlertAt.getTime() > ALERT_AFTER_MS)) {
    await alert("mcmirror.alert", `${def.type} mirror has been failing since ${failingSince.toISOString()}: ${r.error ?? "unknown error"}`);
    lastAlertAt = now;
  }
  await db.mcMirrorRun.update({
    where: { id: runId },
    data: { status: r.status, finishedAt: now, stats: (r.stats ?? undefined) as any, error: r.error ?? null },
  });
  await db.mcMirrorProvider.update({
    where: { key: def.type },
    data: {
      leaseUntil: null,
      nextRunAt,
      lastOkAt: failed ? row?.lastOkAt ?? null : now,
      lastError: r.error ?? (r.stats?.errors.length ? r.stats.errors.slice(0, 3).join("; ").slice(0, 500) : null),
      failingSince,
      consecutiveFailures: consecutive,
      lastAlertAt,
      lastStats: (r.stats ?? undefined) as any,
    },
  });
  void trigger;
}

/** Quota check: AuditLog alert at most once per 24 h when the dataset is >90 % full. */
export async function checkQuota(): Promise<{ usedPct: number } | null> {
  const u = await datasetUsage();
  if (!u) return null;
  if (u.usedPct > QUOTA_ALERT_PCT) {
    const recent = await db.auditLog.findFirst({ where: { action: "mcmirror.quota", createdAt: { gt: new Date(Date.now() - ALERT_AFTER_MS) } } });
    if (!recent) await alert("mcmirror.quota", `NX Labs mirror dataset is ${u.usedPct}% full (${Math.round(u.freeBytes / 1024 ** 3)} GiB free)`);
  }
  return { usedPct: u.usedPct };
}

/** Run every due provider sequentially. Safe to call often: rows decide what's due. */
export async function runDueProviders(trigger: "timer" | "cli" = "timer"): Promise<RunResult[]> {
  if (!(await mirrorReady({ create: true }))) return [];
  await ensureProviderRows();
  const now = new Date();
  const rows = await db.mcMirrorProvider.findMany({
    where: { enabled: true, OR: [{ runRequested: true }, { paused: false, nextRunAt: { lte: now } }] },
    orderBy: { nextRunAt: "asc" },
  });
  const out: RunResult[] = [];
  for (const row of rows) {
    const def = providerFor(row.key);
    if (!def || !def.enabled()) continue;
    const r = await runProvider(def, row.runRequested ? "run-now" : trigger);
    if (r) out.push(r);
  }
  await checkQuota().catch(() => null);
  return out;
}

/** Summaries for the admin page (all indexes). */
export async function loadIndexes(): Promise<Partial<Record<McType, TypeIndex | null>>> {
  const out: Partial<Record<McType, TypeIndex | null>> = {};
  for (const p of PROVIDERS) out[p.type] = await readIndex(p.type).catch(() => null);
  return out;
}

