/**
 * Guest-facing download URLs: /api/mcjars/<token>/<type>/<mcVersion>/<file>
 *
 * <token> = first 32 base64url chars of HMAC-SHA256(key, "v1:<type>/<mcVersion>/<file>").
 * key     = MC_MIRROR_URL_SECRET, or HMAC(AUTH_SECRET, "nxeon-mcjars-url-v1") when unset.
 *
 * So every file has its own unguessable URL; knowing one URL reveals nothing
 * about any other, nothing is listable, and a bad token is indistinguishable
 * from a missing file (both 404). Rotating the secret invalidates every URL —
 * only servers mid-download would notice (they fall back to upstream).
 *
 * Why /api/mcjars and not /_mcjars: App Router treats `_folders` as private
 * (never routed), and middleware.ts already lets /api/* through on every host.
 */
import { createHmac, timingSafeEqual } from "node:crypto";
import { publicBaseUrl } from "./config";

export const ROUTE_PREFIX = "/api/mcjars";

function key(): Buffer {
  const explicit = process.env.MC_MIRROR_URL_SECRET;
  if (explicit && explicit.length >= 16) return Buffer.from(explicit, "utf8");
  const base = process.env.AUTH_SECRET;
  if (!base) throw new Error("mc mirror: no MC_MIRROR_URL_SECRET or AUTH_SECRET available to sign URLs");
  return createHmac("sha256", base).update("nxeon-mcjars-url-v1").digest();
}

export function tokenFor(type: string, mcVersion: string, file: string): string {
  return createHmac("sha256", key()).update(`v1:${type}/${mcVersion}/${file}`).digest("base64url").slice(0, 32);
}

export function tokenValid(token: string, type: string, mcVersion: string, file: string): boolean {
  if (typeof token !== "string" || !/^[A-Za-z0-9_-]{32}$/.test(token)) return false;
  let expected: string;
  try {
    expected = tokenFor(type, mcVersion, file);
  } catch {
    return false;
  }
  return timingSafeEqual(Buffer.from(token), Buffer.from(expected));
}

export function mirrorPath(type: string, mcVersion: string, file: string): string {
  return `${ROUTE_PREFIX}/${tokenFor(type, mcVersion, file)}/${type}/${encodeURIComponent(mcVersion)}/${encodeURIComponent(file)}`;
}

export function mirrorUrl(type: string, mcVersion: string, file: string): string {
  return `${publicBaseUrl()}${mirrorPath(type, mcVersion, file)}`;
}

