/**
 * Read-only file serving for guests (app/api/mcjars/[...path]/route.ts).
 *
 * Only a file that (a) carries a valid per-file HMAC token, (b) is listed as
 * `mirrored` in its type's index.json and (c) resolves inside the mirror root
 * through `safeJoin` is ever opened. Everything else — bad token, unknown file,
 * traversal attempt, directory, index.json itself — is a plain 404. No listing.
 *
 * Range requests (single range), strong ETag = the file's sha256, 304 on
 * If-None-Match, per-client rate limit, and a global cap on concurrent streams
 * so a provisioning burst can't starve the web process.
 */
import fs from "node:fs";
import fsp from "node:fs/promises";
import { Readable } from "node:stream";
import { mirrorRoot } from "./config";
import { readIndex, safeJoin, validSegment } from "./store";
import { tokenValid } from "./urls";
import type { McType } from "./types";
import { checkRateLimit, clientIp } from "../rate-limit";

export const MAX_CONCURRENT_STREAMS = 12;
export const RATE = { max: 120, windowMs: 10 * 60_000 };
let active = 0;

export function _activeStreams(): number {
  return active;
}

const notFound = () => new Response("Not found", { status: 404, headers: { "Cache-Control": "no-store" } });

export function parseRange(h: string | null, size: number): { start: number; end: number } | "invalid" | null {
  if (!h) return null;
  const m = /^bytes=(\d*)-(\d*)$/.exec(h.trim());
  if (!m) return "invalid";
  let start: number;
  let end: number;
  if (m[1] === "" && m[2] === "") return "invalid";
  if (m[1] === "") {
    const n = Number(m[2]);
    if (!n) return "invalid";
    start = Math.max(0, size - n);
    end = size - 1;
  } else {
    start = Number(m[1]);
    end = m[2] === "" ? size - 1 : Math.min(Number(m[2]), size - 1);
  }
  if (!Number.isFinite(start) || !Number.isFinite(end) || start > end || start >= size) return "invalid";
  return { start, end };
}

export async function serveMirrorFile(
  req: Request,
  segments: string[],
  opts: { root?: string; rateLimit?: boolean } = {},
): Promise<Response> {
  if (segments.length !== 4) return notFound();
  const [token, type, rawVersion, rawFile] = segments;
  let version: string;
  let file: string;
  try {
    version = decodeURIComponent(rawVersion);
    file = decodeURIComponent(rawFile);
  } catch {
    return notFound();
  }
  if (!validSegment("type", type) || !validSegment("version", version) || !validSegment("file", file)) return notFound();
  if (!tokenValid(token, type, version, file)) return notFound();

  if (opts.rateLimit !== false) {
    const rl = checkRateLimit(`mcjars:${clientIp(req.headers)}`, RATE);
    if (!rl.ok) return new Response("Too many requests", { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } });
  }

  const root = opts.root ?? mirrorRoot();
  const ix = await readIndex(type as McType, root);
  const b = ix?.versions[version]?.builds.find((x) => x.fileName === file && x.mirrored && x.sha256);
  if (!b) return notFound();
  let abs: string;
  let size: number;
  try {
    abs = safeJoin(root, type, version, file);
    const st = await fsp.lstat(abs);
    if (!st.isFile()) return notFound(); // never follow a symlink / serve a directory
    size = st.size;
    if (b.size && b.size !== size) return notFound(); // truncated/replaced on disk — treat as absent
  } catch {
    return notFound();
  }

  const etag = `"${b.sha256}"`;
  const base: Record<string, string> = {
    ETag: etag,
    "Accept-Ranges": "bytes",
    "Cache-Control": "private, max-age=31536000, immutable",
    "Content-Type": file.endsWith(".zip") ? "application/zip" : "application/java-archive",
    "Content-Disposition": `attachment; filename="${file}"`,
    "X-Content-Type-Options": "nosniff",
    "X-Nxeon-Sha256": b.sha256!,
  };
  const inm = req.headers.get("if-none-match");
  if (inm && inm.split(",").map((s) => s.trim().replace(/^W\//, "")).includes(etag)) {
    return new Response(null, { status: 304, headers: base });
  }
  const range = parseRange(req.headers.get("range"), size);
  if (range === "invalid") return new Response(null, { status: 416, headers: { ...base, "Content-Range": `bytes */${size}` } });
  const start = range ? range.start : 0;
  const end = range ? range.end : size - 1;
  const headers = { ...base, "Content-Length": String(end - start + 1), ...(range ? { "Content-Range": `bytes ${start}-${end}/${size}` } : {}) };
  const status = range ? 206 : 200;
  if (req.method === "HEAD") return new Response(null, { status, headers });

  if (active >= MAX_CONCURRENT_STREAMS) {
    return new Response("Busy", { status: 503, headers: { "Retry-After": "15", "Cache-Control": "no-store" } });
  }
  active++;
  let released = false;
  const release = () => {
    if (!released) {
      released = true;
      active--;
    }
  };
  const stream = fs.createReadStream(abs, { start, end });
  stream.on("close", release);
  stream.on("error", release);
  return new Response(Readable.toWeb(stream) as unknown as ReadableStream, { status, headers });
}

