import { serveMirrorFile } from "@/lib/mcjars/serve";

/**
 * Minecraft server-software mirror — read-only, tokenised, rate-limited file
 * serving for our own game-server VMs. See lib/mcjars/serve.ts + urls.ts and
 * docs § "Minecraft server-software mirror". Not a public download page.
 */
export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type Ctx = { params: Promise<{ path: string[] }> };

export async function GET(req: Request, ctx: Ctx) {
  const { path } = await ctx.params;
  return serveMirrorFile(req, path ?? []);
}

export async function HEAD(req: Request, ctx: Ctx) {
  const { path } = await ctx.params;
  return serveMirrorFile(req, path ?? []);
}

