/**
 * Pinning a Minecraft server to an exact mirrored jar — PURE helpers shared by
 * provisioning (worker/game-variant.ts), settings-apply (worker/game-config.ts)
 * and the rescue tool (scripts/mc-pin-jar.ts). Tested in test/mcjars.test.ts.
 *
 * WHY (incident 2026-10-01): itzg/minecraft-server re-resolves and re-downloads
 * the server jar from the internet on EVERY container start (TYPE=PAPER →
 * fill.papermc.io, VANILLA → Mojang manifest, …). PaperMC's whole download API
 * returned 503 for hours and a customer's Paper server crash-looped 100+ times
 * on plain restarts. Pinned, the jar lives on the server's own /opt/mc volume
 * and the image is told to use that file — restarts never contact upstream.
 *
 * Per-type env, verified against the itzg scripts (master, 2026-10-01 —
 * scripts/start-deploy*, the java25 tag is built from it):
 *   vanilla  TYPE=CUSTOM  CUSTOM_SERVER=<jar>  FAMILY=VANILLA     (start-deployCustom; FAMILY override honoured)
 *   paper    TYPE=PAPER   PAPER_CUSTOM_JAR=<jar>                  (start-deployPaper: skips mc-image-helper install-paper)
 *   folia    TYPE=FOLIA   PAPER_CUSTOM_JAR=<jar>                  (start-deployFolia execs start-deployPaper)
 *   purpur   TYPE=CUSTOM  CUSTOM_SERVER=<jar>  FAMILY=SPIGOT      (start-deployPurpur has no local-file option)
 *   fabric   TYPE=FABRIC  FABRIC_LAUNCHER=<jar>                   (install-fabric-loader --from-local-file)
 *   forge    TYPE=FORGE   FORGE_INSTALLER=<jar>                   (ProvidedInstallerResolver: version read from the jar)
 *   neoforge TYPE=NEOFORGE NEOFORGE_INSTALLER=<jar>
 * plus, for the Paper family, SKIP_DOWNLOAD_DEFAULTS=true: start-deployPaper
 * otherwise fetches default bukkit/spigot/paper-global.yml from GitHub on every
 * start (warning-only, but a pointless upstream call + delay; Paper generates
 * its own defaults). NXEON_MCJAR=<type>:<version>:<build>:<sha256> is a marker
 * the platform reads back from `docker inspect` to know what is running.
 */
import type { McType } from "./types";

/** Host path (bind-mounted to /data in the `mc` container). */
export const HOST_JAR_DIR = "/opt/mc/.nxeon/jars";
export const CONTAINER_JAR_DIR = "/data/.nxeon/jars";
export const PIN_ENV_FILE = "/root/mc-pin.env";

/** Env keys this module owns — stripped before writing a new pin (or the upstream fallback). */
export const PIN_KEYS = [
  "TYPE",
  "CUSTOM_SERVER",
  "PAPER_CUSTOM_JAR",
  "FABRIC_LAUNCHER",
  "FORGE_INSTALLER",
  "NEOFORGE_INSTALLER",
  "FAMILY",
  "SKIP_DOWNLOAD_DEFAULTS",
  "NXEON_MCJAR",
  // stale upstream selectors that would fight a pin
  "PAPER_BUILD",
  "PAPERBUILD",
  "PAPER_DOWNLOAD_URL",
  "PURPUR_BUILD",
  "PURPUR_DOWNLOAD_URL",
  "FABRIC_LOADER_VERSION",
  "FABRIC_LAUNCHER_VERSION",
  "FABRIC_INSTALLER_VERSION",
  "FABRIC_LAUNCHER_URL",
  "FORGE_VERSION",
  "FORGE_INSTALLER_URL",
  "NEOFORGE_VERSION",
] as const;

export const PINNABLE_TYPES = ["vanilla", "paper", "folia", "purpur", "fabric", "forge", "neoforge"] as const;
export type PinnableType = (typeof PINNABLE_TYPES)[number];
export function isPinnable(t: string): t is PinnableType {
  return (PINNABLE_TYPES as readonly string[]).includes(t);
}

export interface PinPlan {
  type: PinnableType;
  mcVersion: string;
  build: string;
  fileName: string;
  sha256: string;
  size: number | null;
  url: string;
  channel: string;
  source: "mirror" | "self-built" | "guest-local";
}

const SAFE_FILE = /^[A-Za-z0-9][A-Za-z0-9._+-]{0,150}\.jar$/;
const SAFE_VERSION = /^[0-9A-Za-z][0-9A-Za-z._+-]{0,40}$/;
const SAFE_BUILD = /^[A-Za-z0-9][A-Za-z0-9._+-]{0,60}$/;
const SAFE_URL = /^https:\/\/[A-Za-z0-9.-]+(:\d+)?\/[A-Za-z0-9._~%/+-]*$/;

/** Every value that reaches a shell line must pass this (no quoting games — allowlists only). */
export function assertShellSafe(p: Pick<PinPlan, "type" | "mcVersion" | "build" | "fileName" | "sha256" | "url">): void {
  if (!isPinnable(p.type)) throw new Error("pin: bad type");
  if (!SAFE_VERSION.test(p.mcVersion)) throw new Error("pin: bad version");
  if (!SAFE_BUILD.test(p.build)) throw new Error("pin: bad build");
  if (!SAFE_FILE.test(p.fileName)) throw new Error("pin: bad file name");
  if (!/^[a-f0-9]{64}$/.test(p.sha256)) throw new Error("pin: bad sha256");
  if (!SAFE_URL.test(p.url)) throw new Error("pin: bad url");
}

export function markerValue(p: Pick<PinPlan, "type" | "mcVersion" | "build" | "sha256">): string {
  return `${p.type}:${p.mcVersion}:${p.build}:${p.sha256.slice(0, 16)}`;
}

export function parseMarker(v: string | null | undefined): { type: string; mcVersion: string; build: string; sha16: string } | null {
  const m = /^([a-z]+):([0-9A-Za-z._+-]+):([A-Za-z0-9._+-]+):([a-f0-9]{16})$/.exec(v ?? "");
  return m ? { type: m[1], mcVersion: m[2], build: m[3], sha16: m[4] } : null;
}

/** The container env that runs exactly `fileName` (a path under /data). */
export function pinnedEnv(p: Pick<PinPlan, "type" | "mcVersion" | "build" | "fileName" | "sha256">, jarPathInContainer?: string): Record<string, string> {
  const jar = jarPathInContainer ?? `${CONTAINER_JAR_DIR}/${p.fileName}`;
  const marker = { NXEON_MCJAR: markerValue(p) };
  switch (p.type) {
    case "vanilla":
      return { TYPE: "CUSTOM", CUSTOM_SERVER: jar, FAMILY: "VANILLA", ...marker };
    case "paper":
      return { TYPE: "PAPER", PAPER_CUSTOM_JAR: jar, SKIP_DOWNLOAD_DEFAULTS: "true", ...marker };
    case "folia":
      return { TYPE: "FOLIA", PAPER_CUSTOM_JAR: jar, SKIP_DOWNLOAD_DEFAULTS: "true", ...marker };
    case "purpur":
      return { TYPE: "CUSTOM", CUSTOM_SERVER: jar, FAMILY: "SPIGOT", ...marker };
    case "fabric":
      return { TYPE: "FABRIC", FABRIC_LAUNCHER: jar, ...marker };
    case "forge":
      return { TYPE: "FORGE", FORGE_INSTALLER: jar, ...marker };
    case "neoforge":
      return { TYPE: "NEOFORGE", NEOFORGE_INSTALLER: jar, ...marker };
  }
}

/** The pre-mirror behaviour: let the image resolve + download the type from upstream on each start. */
export function upstreamEnv(variant: string): Record<string, string> {
  const t = (variant || "vanilla").toUpperCase();
  if (!/^[A-Z_]{2,20}$/.test(t)) throw new Error("bad variant");
  return { TYPE: t };
}

/** Apply a pin (or the upstream fallback) to a container env map in place: strip every owned key, then set. */
export function applyEnv(env: Map<string, string>, next: Record<string, string>): Map<string, string> {
  for (const k of PIN_KEYS) env.delete(k);
  for (const [k, v] of Object.entries(next)) env.set(k, v);
  return env;
}

function envFileLines(env: Record<string, string>): string {
  // printf-safe: every value comes from pinnedEnv/upstreamEnv over allowlisted inputs (no %, ', \ or newlines possible).
  return Object.entries(env)
    .map(([k, v]) => `${k}=${v}`)
    .join("\\n");
}

/**
 * One-line bash that stages the jar on the GUEST and writes PIN_ENV_FILE with
 * either the pinned env (download + sha256 verified) or the upstream fallback
 * env (any failure) — so a mirror hiccup during provisioning degrades to the
 * old behaviour instead of a broken server. Never exits non-zero.
 */
export function stageScript(p: PinPlan, fallbackVariant: string): string {
  assertShellSafe(p);
  const part = `${HOST_JAR_DIR}/${p.fileName}.part`;
  const dest = `${HOST_JAR_DIR}/${p.fileName}`;
  const pinned = envFileLines(pinnedEnv(p));
  const fallback = envFileLines(upstreamEnv(fallbackVariant));
  return [
    `mkdir -p ${HOST_JAR_DIR}`,
    `if [ -f ${dest} ] && echo '${p.sha256}  ${dest}' | sha256sum -c --status; then NXJ=ok; ` +
      `elif curl -fsSL --retry 4 --retry-delay 5 --connect-timeout 15 --max-time 900 -A nxeon-mcjar/1 -o ${part} '${p.url}' && echo '${p.sha256}  ${part}' | sha256sum -c --status; then mv -f ${part} ${dest} && NXJ=ok; ` +
      `else rm -f ${part}; NXJ=fail; fi`,
    `if [ "$NXJ" = ok ]; then printf '${pinned}\\n' > ${PIN_ENV_FILE}; echo "NXEON_MCJAR staged ${p.type} ${p.mcVersion} ${p.build}"; ` +
      `else printf '${fallback}\\n' > ${PIN_ENV_FILE}; echo "NXEON_MCJAR staging failed - upstream fallback"; fi`,
    `chmod 600 ${PIN_ENV_FILE}`,
  ].join("; ");
}

/**
 * Rewrite a Minecraft setup script (`… && docker run -d -e TYPE=PAPER … itzg/minecraft-server:javaNN`)
 * to stage `p` first and take TYPE + the jar selector from PIN_ENV_FILE.
 * Must run BEFORE wrapDockerGameService (which turns `docker run -d` into `docker create` + a unit).
 * Idempotent; returns the script unchanged when it doesn't have the expected shape.
 */
export function applyPinToSetupScript(setupScript: string, p: PinPlan, fallbackVariant: string): string {
  if (setupScript.includes(PIN_ENV_FILE)) return setupScript;
  const m = /docker run\s+(?:-d|--detach)\b/.exec(setupScript);
  if (!m) return setupScript;
  let out = setupScript.replace(/\s-e\s+TYPE=(?:'[^']*'|"[^"]*"|\S*)/, "");
  // A LATEST version resolves to the concrete pinned version (the pin IS the version now).
  out = out.replace(/-e\s+VERSION=(?:'[^']*'|"[^"]*"|\S*)/, `-e VERSION='${p.mcVersion}'`);
  const idx = out.search(/docker run\s+(?:-d|--detach)\b/);
  const head = out.slice(0, idx);
  const tail = out.slice(idx).replace(/^(docker run\s+(?:-d|--detach)\b)/, `$1 --env-file ${PIN_ENV_FILE}`);
  // `{ …; }` keeps the stage step a single && link that always succeeds.
  return `${head}{ ${stageScript(p, fallbackVariant)}; } && ${tail}`;
}

