/**
 * Worker-side decision: can this Minecraft server be pinned to a mirrored jar
 * right now? Reads the on-disk index (no DB needed for the decision itself) and
 * HEAD-checks our own public URL — the same one the guest will download from —
 * so a broken serving path degrades to the old upstream behaviour instead of
 * a failed provision. Returns `{ plan: null, reason }` whenever anything is off.
 */
import { mirrorReady, mirrorRoot } from "./config";
import { readIndex } from "./store";
import { mirrorUrl } from "./urls";
import { isPinnable, type PinPlan, type PinnableType } from "./pin";
import type { IndexBuild, IndexVersion, McType, TypeIndex } from "./types";

export interface PickOpts {
  /** Exact build the owner asked for (scripts/mc-pin-jar.ts --build, or an explicit update). */
  requestedBuild?: string | null;
  /** Self-built (from-git) jars are eligible only while the official provider is failing, or when requested explicitly. */
  allowSelfBuilt?: boolean;
}

/** Which mirrored build to run for a version. Official > self-built; stable > experimental. */
export function pickBuild(ver: IndexVersion | undefined, opts: PickOpts = {}): IndexBuild | null {
  if (!ver) return null;
  const mirrored = ver.builds.filter((b) => b.mirrored && b.sha256);
  if (opts.requestedBuild) return mirrored.find((b) => b.build === opts.requestedBuild) ?? null;
  const official = mirrored.filter((b) => b.channel !== "self-built");
  const hasStableAnywhere = ver.builds.some((b) => b.channel === "stable" && !b.gone);
  const stable = official.find((b) => b.channel === "stable");
  if (stable) return stable;
  if (!hasStableAnywhere && official[0]) return official[0];
  if (opts.allowSelfBuilt) return mirrored.find((b) => b.channel === "self-built") ?? null;
  return null;
}

/** "LATEST" → the newest stable version of this type that has a pickable mirrored build. */
export function resolveVersion(ix: TypeIndex, want: string, opts: PickOpts = {}): string | null {
  if (want !== "LATEST") return ix.versions[want] ? want : null;
  for (const v of ix.order) {
    const ver = ix.versions[v];
    if (ver?.channel === "stable" && pickBuild(ver, opts)) return v;
  }
  return null;
}

/** For R's auto-update (worker/game-update.ts): newest mirrored stable version+build of a type. */
export async function newestPinnable(type: McType, root = mirrorRoot()): Promise<{ mcVersion: string; build: string; sha256: string } | null> {
  const ix = await readIndex(type, root);
  if (!ix) return null;
  const v = resolveVersion(ix, "LATEST");
  const b = v ? pickBuild(ix.versions[v]) : null;
  return v && b?.sha256 ? { mcVersion: v, build: b.build, sha256: b.sha256 } : null;
}

/** Newest mirrored build for a FIXED version (auto-update within a version line: e.g. Paper 26.2 build 17 → 23). */
export async function newestBuildFor(type: McType, mcVersion: string, root = mirrorRoot()): Promise<{ build: string; sha256: string } | null> {
  const ix = await readIndex(type, root);
  const b = pickBuild(ix?.versions[mcVersion]);
  return b?.sha256 ? { build: b.build, sha256: b.sha256 } : null;
}

export type PlanResult = { plan: PinPlan; reason?: undefined } | { plan: null; reason: string };

export async function headCheck(url: string, sha256: string, fetchImpl: typeof fetch = fetch): Promise<string | null> {
  try {
    const r = await fetchImpl(url, { method: "HEAD", signal: AbortSignal.timeout(4000), redirect: "manual" });
    if (r.status !== 200) return `mirror URL answered ${r.status}`;
    const got = r.headers.get("x-nxeon-sha256");
    if (got && got !== sha256) return "mirror URL serves a different file than the index says";
    return null;
  } catch (e) {
    return `mirror URL unreachable (${e instanceof Error ? e.message : String(e)})`;
  }
}

export async function planPin(
  input: { type: string; version: string; requestedBuild?: string | null; allowSelfBuilt?: boolean },
  opts: { root?: string; fetchImpl?: typeof fetch; skipHead?: boolean } = {},
): Promise<PlanResult> {
  if (!isPinnable(input.type)) return { plan: null, reason: `type ${input.type} is not pinnable` };
  if (!opts.root && !(await mirrorReady())) return { plan: null, reason: "mirror is not provisioned/enabled on this host" };
  const ix = await readIndex(input.type as McType, opts.root ?? mirrorRoot());
  if (!ix) return { plan: null, reason: `no ${input.type} index yet` };
  const pick = { requestedBuild: input.requestedBuild, allowSelfBuilt: input.allowSelfBuilt };
  const version = resolveVersion(ix, input.version, pick);
  if (!version) return { plan: null, reason: `${input.type} ${input.version} is not in the mirror` };
  const b = pickBuild(ix.versions[version], pick);
  if (!b || !b.sha256) return { plan: null, reason: `no mirrored ${input.type} ${version} build${input.requestedBuild ? ` ${input.requestedBuild}` : ""}` };
  if (!b.fileName.endsWith(".jar")) return { plan: null, reason: "not a jar" };
  const url = mirrorUrl(input.type, version, b.fileName);
  if (!opts.skipHead) {
    const err = await headCheck(url, b.sha256, opts.fetchImpl);
    if (err) return { plan: null, reason: err };
  }
  return {
    plan: {
      type: input.type as PinnableType,
      mcVersion: version,
      build: b.build,
      fileName: b.fileName,
      sha256: b.sha256,
      size: b.size ?? null,
      url,
      channel: b.channel,
      source: b.channel === "self-built" ? "self-built" : "mirror",
    },
  };
}

