/**
 * Worker hook for the Minecraft server-software mirror (lib/mcjars). Called
 * every minute from worker/index.ts as fire-and-forget; does nothing unless a
 * provider is due (6 h cadence, backoff after failures, sooner while a
 * download backlog remains, or an admin "Run now"). Overlap: this module's
 * `busy` flag + a per-provider DB lease (McMirrorProvider.leaseUntil).
 * Kill switch: MC_MIRROR_DISABLED=1. Missing dataset root → no-op.
 */
import { runDueProviders } from "../lib/mcjars/runner";

let busy = false;

export async function mcMirrorTick(): Promise<void> {
  if (busy || process.env.MC_MIRROR_DISABLED === "1") return;
  busy = true;
  try {
    const results = await runDueProviders("timer");
    for (const r of results) {
      const s = r.stats;
      console.log(
        `[mcmirror] ${r.type}: ${r.status}` +
          (s ? ` versions=${s.versions} +${s.downloaded} files (${Math.round(s.downloadedBytes / 1048576)} MB) failed=${s.failed} gone=${s.gone} evicted=${s.evicted} corrupt=${s.corrupt} backlog=${s.backlog}` : "") +
          (r.error ? ` error=${r.error}` : ""),
      );
    }
  } catch (e) {
    console.error("[mcmirror] tick error", e instanceof Error ? e.message : e);
  } finally {
    busy = false;
  }
}
EOF
