"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { recordAudit } from "./audit";
import { providerFor, PROVIDERS } from "./mcjars/registry";

/**
 * Admin controls for /admin/mc-mirror. They only flip flags on
 * McMirrorProvider rows — the worker (worker/mcmirror.ts) does every upstream
 * call and file write, so the web app never downloads anything itself.
 * Idempotent; every call is audited.
 */
type Action = "run-now" | "pause" | "resume";

export async function adminMcMirrorControl(key: string, action: Action): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireArea("fleet");
  if (!["run-now", "pause", "resume"].includes(action)) return { error: "Unknown action." };
  const keys = key === "all" ? PROVIDERS.map((p) => p.type) : providerFor(key) ? [key] : [];
  if (!keys.length) return { error: "Unknown provider." };
  for (const k of keys) {
    const data =
      action === "run-now"
        ? { runRequested: true, nextRunAt: new Date() }
        : action === "pause"
          ? { paused: true }
          : { paused: false, nextRunAt: new Date() };
    await db.mcMirrorProvider.upsert({ where: { key: k }, create: { key: k, ...data }, update: data });
  }
  await recordAudit(admin.id, "mcmirror.control", `${key} → ${action}`);
  revalidatePath("/admin/mc-mirror");
  return { ok: true };
}
