"use client";

import { useState, useTransition } from "react";
import { adminMcMirrorControl } from "@/lib/actions-admin-mcmirror";

export function McMirrorControls({ providerKey, paused }: { providerKey: string; paused?: boolean }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  const go = (a: "run-now" | "pause" | "resume") =>
    start(async () => {
      const r = await adminMcMirrorControl(providerKey, a);
      setMsg(r.error ?? (a === "run-now" ? "Queued — the worker picks it up within a minute." : null));
    });
  const all = providerKey === "all";
  return (
    <div className="flex flex-wrap items-center gap-2">
      <button className="btn-primary py-1 text-xs" disabled={pending} onClick={() => go("run-now")}>
        {all ? "Run all now" : "Run now"}
      </button>
      {all ? (
        <>
          <button className="btn-secondary py-1 text-xs" disabled={pending} onClick={() => window.confirm("Pause every provider's 6-hourly schedule?") && go("pause")}>
            Pause all
          </button>
          <button className="btn-secondary py-1 text-xs" disabled={pending} onClick={() => go("resume")}>Resume all</button>
        </>
      ) : paused ? (
        <button className="btn-secondary py-1 text-xs" disabled={pending} onClick={() => go("resume")}>Resume</button>
      ) : (
        <button className="btn-secondary py-1 text-xs" disabled={pending} onClick={() => go("pause")}>Pause</button>
      )}
      {msg && <span className="text-xs text-slate-400">{msg}</span>}
    </div>
  );
}
