import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, StatCard, fmtBytes, timeAgo } from "@/components/ui/primitives";
import { McMirrorControls } from "@/components/admin/McMirrorControls";
import { PROVIDERS, NOT_MIRRORED } from "@/lib/mcjars/registry";
import { datasetRoot, datasetUsage, mirrorMaxBytes, mirrorReady, mirrorRoot } from "@/lib/mcjars/config";
import { readIndex, mirroredBytes } from "@/lib/mcjars/store";
import { ALERT_AFTER_MS, QUOTA_ALERT_PCT } from "@/lib/mcjars/runner";
import type { TypeIndex } from "@/lib/mcjars/types";

export const dynamic = "force-dynamic";

const OWNER_CMD = "zfs create -o quota=100G -o mountpoint=/tank/nxlabs-mirror tank/nxlabs-mirror && chown nxeon:nxeon /tank/nxlabs-mirror";

function when(d: Date | null | undefined): string {
  if (!d) return "never";
  const s = Math.round((d.getTime() - Date.now()) / 1000);
  if (s > 0) return s < 3600 ? `in ${Math.ceil(s / 60)}m` : `in ${Math.round(s / 3600)}h`;
  return timeAgo(d);
}

const tone = (s: string | undefined | null): "green" | "red" | "amber" | "slate" =>
  s === "ok" ? "green" : s === "error" ? "red" : s === "partial" || s === "running" ? "amber" : "slate";

/** Read-only status of the Minecraft server-software mirror; the only controls are run-now / pause (audited). */
export default async function AdminMcMirrorPage() {
  await requireArea("fleet");
  const ready = await mirrorReady();
  const [rows, runs, pins, usage] = await Promise.all([
    db.mcMirrorProvider.findMany().catch(() => []),
    db.mcMirrorRun.findMany({ orderBy: { startedAt: "desc" }, take: 20 }).catch(() => []),
    db.mcJarPin.findMany({ orderBy: { updatedAt: "desc" }, take: 25 }).catch(() => []),
    datasetUsage(),
  ]);
  const pinCounts = await db.mcJarPin.groupBy({ by: ["state"], _count: true }).catch(() => [] as { state: string; _count: number }[]);
  const indexes = new Map<string, TypeIndex | null>();
  if (ready) for (const p of PROVIDERS) indexes.set(p.type, await readIndex(p.type).catch(() => null));
  const byKey = new Map(rows.map((r) => [r.key, r]));
  const totalMirrored = [...indexes.values()].reduce((s, ix) => s + mirroredBytes(ix).bytes, 0);
  const totalFiles = [...indexes.values()].reduce((s, ix) => s + mirroredBytes(ix).files, 0);
  const failingLong = rows.filter((r) => r.failingSince && Date.now() - r.failingSince.getTime() > ALERT_AFTER_MS);
  const quotaHot = usage && usage.usedPct > QUOTA_ALERT_PCT;

  return (
    <div>
      <PageHeader
        title="Minecraft jar mirror"
        sub="Local copies of every Minecraft server type our servers run, so provisioning and restarts never depend on an outside download API. The worker refreshes it every ~6 h."
      >
        <McMirrorControls providerKey="all" />
      </PageHeader>

      {!ready && (
        <div className="card mb-6 border-amber-500/40">
          <p className="font-semibold text-amber-300">Mirror is OFF — the storage dataset doesn&apos;t exist yet.</p>
          <p className="mt-1 text-sm text-slate-400">
            Everything falls back to the old behaviour (each server downloads from upstream on every start). The code never creates the dataset itself. Owner, once, on the primary:
          </p>
          <pre className="mt-2 overflow-x-auto rounded-lg bg-black/40 p-3 text-xs text-slate-200">{OWNER_CMD}</pre>
          <p className="mt-1 text-xs text-slate-500">Expected root: {mirrorRoot()} (dataset {datasetRoot()}). Override with MC_MIRROR_DIR / NXLABS_MIRROR_DIR.</p>
        </div>
      )}
      {(failingLong.length > 0 || quotaHot) && (
        <div className="card mb-6 border-red-500/40">
          {failingLong.map((r) => (
            <p key={r.key} className="text-sm text-red-300">
              <strong>{r.key}</strong> has been failing since {r.failingSince!.toISOString().slice(0, 16).replace("T", " ")} UTC: {r.lastError ?? "unknown error"}
            </p>
          ))}
          {quotaHot && <p className="text-sm text-red-300">Mirror dataset is {usage!.usedPct}% full ({fmtBytes(usage!.freeBytes)} free).</p>}
        </div>
      )}

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Mirrored" value={fmtBytes(totalMirrored)} delta={`of ${fmtBytes(mirrorMaxBytes())} budget`} />
        <StatCard label="Files" value={totalFiles.toLocaleString()} />
        <StatCard label="Dataset used" value={usage ? `${usage.usedPct}%` : "n/a"} delta={usage ? `${fmtBytes(usage.freeBytes)} free` : undefined} deltaGood={!quotaHot} />
        <StatCard
          label="Pinned servers"
          value={String(pinCounts.find((p) => p.state === "ACTIVE")?._count ?? 0)}
          delta={`${pinCounts.find((p) => p.state === "PLANNED")?._count ?? 0} planned · ${pinCounts.find((p) => p.state === "FALLBACK")?._count ?? 0} on upstream`}
        />
      </div>

      <h2 className="mb-2 text-lg font-semibold">Providers</h2>
      <div className="mb-8 space-y-2">
        {PROVIDERS.map((p) => {
          const r = byKey.get(p.type);
          const ix = indexes.get(p.type) ?? null;
          const st = (r?.lastStats ?? {}) as Record<string, unknown>;
          const u = mirroredBytes(ix);
          const newest = ix ? ix.order.filter((v) => ix.versions[v]?.channel === "stable").slice(0, 4) : [];
          const selfBuilt = ix ? Object.values(ix.versions).flatMap((v) => v.builds.filter((b) => b.channel === "self-built")).length : 0;
          const lastRun = runs.find((x) => x.type === p.type);
          return (
            <div key={p.type} className="card">
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2 font-medium">
                    {p.label}
                    <Badge tone={tone(lastRun?.status)}>{lastRun?.status ?? "not run yet"}</Badge>
                    {r?.paused && <Badge tone="amber">paused</Badge>}
                    {!p.enabled() && <Badge tone="slate">disabled by env</Badge>}
                    {selfBuilt > 0 && <Badge tone="amber">{selfBuilt} self-built</Badge>}
                  </div>
                  <p className="mt-1 text-xs text-slate-400">
                    {u.files} files · {fmtBytes(u.bytes)} · {ix?.order.length ?? 0} versions known · source {ix?.source ?? "—"} · last OK {when(r?.lastOkAt)} · next {when(r?.nextRunAt)}
                    {typeof st.backlog === "number" && st.backlog > 0 ? ` · backlog ${st.backlog}` : ""}
                  </p>
                  {newest.length > 0 && (
                    <p className="mt-1 text-xs text-slate-300">
                      Newest:{" "}
                      {newest.map((v) => {
                        const ver = ix!.versions[v];
                        const b = ver.builds.find((x) => x.build === (ver.latestStableBuild ?? ver.latestBuild));
                        return (
                          <span key={v} className="mr-3">
                            {v}
                            {ver.latestStableBuild && ver.latestStableBuild !== v ? ` #${ver.latestStableBuild}` : ""}
                            {b?.mirrored ? " ✓" : " (not mirrored)"}
                          </span>
                        );
                      })}
                    </p>
                  )}
                  {r?.lastError && <p className="mt-1 break-all text-xs text-red-300">{r.lastError}</p>}
                  <p className="mt-1 text-[11px] text-slate-500">{p.terms}</p>
                </div>
                <McMirrorControls providerKey={p.type} paused={r?.paused} />
              </div>
            </div>
          );
        })}
        {NOT_MIRRORED.map((n) => (
          <div key={n.type} className="card opacity-80">
            <p className="font-medium">
              {n.type} <Badge tone="slate">not mirrored</Badge>
            </p>
            <p className="mt-1 text-xs text-slate-400">{n.why}</p>
          </div>
        ))}
      </div>

      <h2 className="mb-2 text-lg font-semibold">Recent runs</h2>
      <div className="card mb-8 overflow-x-auto p-0">
        <table className="w-full text-left text-sm">
          <thead className="text-xs text-slate-400">
            <tr>
              <th className="px-4 py-2">Type</th>
              <th className="px-4 py-2">Trigger</th>
              <th className="px-4 py-2">Status</th>
              <th className="px-4 py-2">Started</th>
              <th className="px-4 py-2">Result</th>
            </tr>
          </thead>
          <tbody>
            {runs.map((r) => {
              const s = (r.stats ?? {}) as Record<string, number>;
              return (
                <tr key={r.id} className="border-t border-white/[0.06]">
                  <td className="px-4 py-2">{r.type}</td>
                  <td className="px-4 py-2 text-slate-400">{r.trigger}</td>
                  <td className="px-4 py-2"><Badge tone={tone(r.status)}>{r.status}</Badge></td>
                  <td className="px-4 py-2 text-slate-400">{timeAgo(r.startedAt)}</td>
                  <td className="px-4 py-2 text-xs text-slate-400">
                    {r.error ? <span className="text-red-300">{r.error.slice(0, 160)}</span> : `+${s.downloaded ?? 0} files, ${s.failed ?? 0} failed, ${s.evicted ?? 0} evicted, ${s.corrupt ?? 0} corrupt`}
                  </td>
                </tr>
              );
            })}
            {runs.length === 0 && (
              <tr>
                <td className="px-4 py-4 text-slate-500" colSpan={5}>No runs yet.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <h2 className="mb-2 text-lg font-semibold">Server pins</h2>
      <div className="card overflow-x-auto p-0">
        <table className="w-full text-left text-sm">
          <thead className="text-xs text-slate-400">
            <tr>
              <th className="px-4 py-2">Server</th>
              <th className="px-4 py-2">Type / version / build</th>
              <th className="px-4 py-2">State</th>
              <th className="px-4 py-2">Updated</th>
              <th className="px-4 py-2">Detail</th>
            </tr>
          </thead>
          <tbody>
            {pins.map((p) => (
              <tr key={p.id} className="border-t border-white/[0.06]">
                <td className="px-4 py-2 font-mono text-xs">
                  <a className="hover:underline" href={`/admin/servers/${p.serverId}`}>{p.serverId}</a>
                </td>
                <td className="px-4 py-2">{p.type} {p.mcVersion}{p.build ? ` #${p.build}` : ""}{p.source !== "mirror" ? ` (${p.source})` : ""}</td>
                <td className="px-4 py-2"><Badge tone={p.state === "ACTIVE" ? "green" : p.state === "PLANNED" ? "brand" : "amber"}>{p.state}</Badge></td>
                <td className="px-4 py-2 text-slate-400">{timeAgo(p.updatedAt)}</td>
                <td className="px-4 py-2 text-xs text-slate-400">{p.detail}</td>
              </tr>
            ))}
            {pins.length === 0 && (
              <tr>
                <td className="px-4 py-4 text-slate-500" colSpan={5}>No server has been pinned yet.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

