/**
 * Minecraft server-software mirror — manual runner.
 *
 *   # the real thing (owner, on the primary, after the dataset exists): run due/selected providers,
 *   # recorded in McMirrorRun exactly like the worker does
 *   npx tsx scripts/mcmirror.ts --types paper,vanilla
 *
 *   # DB-free dry run into any directory (no McMirror* rows, no in-use info):
 *   npx tsx scripts/mcmirror.ts --no-db --root /tmp/mcm --types fabric --max-downloads 3
 *   npx tsx scripts/mcmirror.ts --no-db --root /tmp/mcm --metadata-only      # size estimate, downloads nothing
 *
 * --metadata-only prints, per type, what the retention policy WOULD download and its size.
 */
import fs from "node:fs/promises";
import { PROVIDERS } from "../lib/mcjars/registry";
import { syncProvider } from "../lib/mcjars/sync";
import { planRetention, readIndex } from "../lib/mcjars/store";
import { hotVersionCount, keepBuildsHot, mirrorMaxBytes, versionScope } from "../lib/mcjars/config";

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`);
  return i > 0 ? process.argv[i + 1] : undefined;
}
const flag = (name: string) => process.argv.includes(`--${name}`);

async function main() {
  const types = (arg("types") ?? PROVIDERS.map((p) => p.type).join(",")).split(",").map((s) => s.trim());
  const defs = PROVIDERS.filter((p) => types.includes(p.type));
  if (!defs.length) throw new Error(`no such types: ${types.join(",")}`);
  const metadataOnly = flag("metadata-only");
  const maxDownloads = metadataOnly ? 0 : arg("max-downloads") ? Number(arg("max-downloads")) : undefined;

  if (!flag("no-db")) {
    const { runProvider } = await import("../lib/mcjars/runner");
    const { mirrorReady } = await import("../lib/mcjars/config");
    if (!(await mirrorReady({ create: true }))) throw new Error("mirror root/dataset missing — see docs (owner zfs command)");
    for (const d of defs) {
      const r = await runProvider(d, "cli", { maxDownloads });
      console.log(JSON.stringify(r ?? { type: d.type, status: "skipped (lease held by another run)" }));
    }
    return;
  }

  const root = arg("root");
  if (!root) throw new Error("--no-db needs --root <dir> (an existing scratch directory)");
  await fs.mkdir(root, { recursive: true });
  let total = 0;
  for (const d of defs) {
    const { stats, index } = await syncProvider(d, {
      root,
      inUse: [],
      usedBytesOtherTypes: 0,
      maxBytes: mirrorMaxBytes(),
      keepHot: keepBuildsHot(),
      hotVersions: hotVersionCount(),
      scope: versionScope(),
      maxDownloads,
      log: (m) => console.log(m),
    });
    const ix = index ?? (await readIndex(d.type, root));
    let planned = 0;
    let plannedFiles = 0;
    let unknown = 0;
    if (ix) {
      const plan = planRetention(ix, { keepHot: keepBuildsHot(), hotVersions: hotVersionCount(), scope: versionScope(), inUse: [], maxBytes: Number.MAX_SAFE_INTEGER, usedBytes: 0 });
      for (const p of plan.download) {
        plannedFiles++;
        if (p.build.size) planned += p.build.size;
        else unknown++;
      }
    }
    total += planned;
    console.log(
      `${d.type}: ${stats.metadataError ? `METADATA ERROR ${stats.metadataError}` : "ok"} versions=${stats.versions} downloaded=${stats.downloaded} (${(stats.downloadedBytes / 1048576).toFixed(1)} MB) failed=${stats.failed} gone=${stats.gone} still-to-download=${plannedFiles} files ≈ ${(planned / 1048576).toFixed(0)} MB${unknown ? ` + ${unknown} of unknown size` : ""}`,
    );
    for (const e of stats.errors.slice(0, 5)) console.log(`   ! ${e}`);
  }
  console.log(`TOTAL still-to-download with known sizes ≈ ${(total / 1024 ** 3).toFixed(2)} GiB`);
}

main().then(
  () => process.exit(0),
  (e) => {
    console.error(e instanceof Error ? e.message : e);
    process.exit(1);
  },
);

