/**
 * Rescue / pin a Minecraft server to an exact server jar.
 *
 * Use when a Minecraft server crash-loops because its container can't
 * download its server software on start (the 2026-10-01 PaperMC 503 outage),
 * or to move an existing server onto a mirrored, pinned jar so restarts stop
 * depending on upstream. DRY-RUN BY DEFAULT — nothing is changed without --apply.
 *
 *   npx tsx scripts/mc-pin-jar.ts <serverId>                                  # plan only
 *   npx tsx scripts/mc-pin-jar.ts <serverId> --inspect                        # + read the container's env over SSH (read-only)
 *   npx tsx scripts/mc-pin-jar.ts <serverId> --type paper --version 26.2 --apply
 *   npx tsx scripts/mc-pin-jar.ts <serverId> --build 17 --apply              # exact mirrored build
 *   npx tsx scripts/mc-pin-jar.ts <serverId> --type paper --version 26.2 --from-guest-jar paper-26.2-17.jar --apply
 *        (mirror lacks it, but the server already downloaded that jar into /opt/mc earlier)
 *
 * --apply: stages the jar on the guest (sha256-verified), rewrites /root/mc.env
 * with the pinned TYPE/jar env, and re-creates the `mc` container through the
 * same recreateGameContainer path Settings uses (stop via systemd, rename,
 * create, start, verify running — rolls back to the old container on any
 * failure). World data on /opt/mc is never touched. If --type/--version differ
 * from the server's saved settings they are saved too (so the next Settings
 * apply doesn't undo the rescue), and an AuditLog row is written.
 *
 * Refuses while the server has a QUEUED/RUNNING job (one in-flight job per server).
 * Run on the primary as root (needs /opt/nxeon/.env for DB + SSH credentials).
 */
import { db } from "../lib/db";
import { planPin } from "../lib/mcjars/plan";
import { isPinnable, type PinnableType } from "../lib/mcjars/pin";
import { variantType } from "../lib/mcjars/runner";

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`);
  return i > 0 ? process.argv[i + 1] : undefined;
}
const flag = (n: string) => process.argv.includes(`--${n}`);

async function main() {
  const serverId = process.argv[2];
  if (!serverId || serverId.startsWith("--")) throw new Error("usage: mc-pin-jar.ts <serverId> [--type t --version v --build b --from-guest-jar f] [--inspect] [--apply]");
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true } });
  if (!server) throw new Error(`server ${serverId} not found`);
  const family = server.gamePlan?.gameFamily ?? server.osTemplate.family;
  if (family !== "minecraft") throw new Error(`${server.hostname} is not a Java Minecraft server (family=${family})`);
  const cfg = (server.gameConfig as Record<string, unknown> | null) ?? {};
  const type = arg("type") ?? variantType(server.gameVariant);
  const version = arg("version") ?? (typeof cfg.VERSION === "string" ? cfg.VERSION : "1.21.1");
  const build = arg("build") ?? null;
  const guestJar = arg("from-guest-jar");
  if (!isPinnable(type)) throw new Error(`type ${type} can't be pinned (pinnable: vanilla paper folia purpur fabric forge neoforge)`);

  console.log(`server   ${server.hostname} (${server.id}) status=${server.status} saved type=${server.gameVariant ?? "vanilla"} version=${String(cfg.VERSION ?? "(default)")}`);
  console.log(`target   ${type} ${version}${build ? ` build ${build}` : ""}${guestJar ? ` using /opt/mc/${guestJar} already on the guest` : " from the mirror"}`);

  let plan = null;
  if (!guestJar) {
    const r = await planPin({ type, version, requestedBuild: build, allowSelfBuilt: !!build });
    if (!r.plan) {
      console.log(`mirror   cannot serve this: ${r.reason}`);
      console.log(`         → options: wait for the mirror to fetch it (Run now on /admin/mc-mirror), pick a version the mirror has,`);
      console.log(`           or --from-guest-jar <file> if the server already has a working jar in /opt/mc (ls /opt/mc/*.jar on the guest).`);
      process.exitCode = 2;
      return;
    }
    plan = r.plan;
    console.log(`mirror   ${plan.fileName} build ${plan.build} (${plan.channel}) sha256 ${plan.sha256.slice(0, 16)}… ${plan.size ? `${(plan.size / 1048576).toFixed(1)} MB` : ""}`);
    console.log(`         ${plan.url.replace(/\/api\/mcjars\/[^/]+\//, "/api/mcjars/<token>/")} (HEAD ok)`);
  }

  const { pinMinecraftServer } = await import("../worker/game-config");
  if (flag("inspect") && !flag("apply")) {
    console.log("inspect  (read-only) — run with --apply to change anything");
  }
  if (!flag("apply")) {
    console.log("DRY RUN  nothing changed. Re-run with --apply.");
    return;
  }
  const inflight = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
  if (inflight) throw new Error(`refusing: ${inflight} job(s) queued/running on this server — wait for them to finish`);

  const res = await pinMinecraftServer(
    server,
    guestJar ? { kind: "guest-local", type: type as PinnableType, mcVersion: version, jar: guestJar } : { kind: "mirror", plan: plan! },
    type,
  );
  for (const n of res.notes) console.log(`         ${n}`);
  if (!res.ok) {
    console.log("FAILED   the previous container was restored (recreateGameContainer rolls back on failure).");
    process.exitCode = 1;
    return;
  }
  const savedVersion = typeof cfg.VERSION === "string" ? cfg.VERSION : null;
  const pinnedVersion = plan?.mcVersion ?? version;
  if ((server.gameVariant ?? "vanilla") !== type || (savedVersion !== pinnedVersion && savedVersion !== "LATEST")) {
    await db.server.update({ where: { id: serverId }, data: { gameVariant: type, gameConfig: { ...cfg, VERSION: pinnedVersion } as any } });
    console.log(`saved    server settings now type=${type} version=${pinnedVersion}`);
  }
  await db.mcJarPin.upsert({
    where: { serverId },
    create: { serverId, type, mcVersion: pinnedVersion, build: res.build ?? null, fileName: plan?.fileName ?? guestJar ?? null, sha256: res.sha256 ?? null, source: guestJar ? "guest-local" : plan!.source, state: "ACTIVE", detail: "pinned by scripts/mc-pin-jar.ts" },
    update: { type, mcVersion: pinnedVersion, build: res.build ?? null, fileName: plan?.fileName ?? guestJar ?? null, sha256: res.sha256 ?? null, source: guestJar ? "guest-local" : plan!.source, state: "ACTIVE", detail: "pinned by scripts/mc-pin-jar.ts" },
  });
  await db.auditLog.create({ data: { userId: null, action: "mcmirror.pin", detail: `${serverId} ${type} ${pinnedVersion} ${res.build ?? ""} via scripts/mc-pin-jar.ts` } });
  console.log("DONE     pinned. Restarts now use the jar on the server's own disk.");
}

main().then(
  () => process.exit(process.exitCode ?? 0),
  (e) => {
    console.error(e instanceof Error ? e.message : e);
    process.exit(1);
  },
);

