/**
 * Paper/Folia SECOND-TIER fallback: build from git when PaperMC's download API is down.
 * See lib/mcjars/providers/paper-git.ts for the policy. This script NEVER builds on
 * the machine it runs on.
 *
 *   # 1. plan (dry-run, any host): resolves the tag/branch + JDK + Gradle tasks from the
 *   #    target ref's README and prints a self-contained builder script
 *   npx tsx scripts/mc-build-paper.ts --project paper --version 26.2
 *   npx tsx scripts/mc-build-paper.ts --project paper --version 26.2 --emit /tmp/build-paper-26.2.sh
 *
 *   # 2. run the emitted script on a SPARE builder VM (docker + git; ~4 GB RAM, ~10 GB disk,
 *   #    10–20 min). It refuses to run on a Proxmox node (/etc/pve). It prints the jar path,
 *   #    commit and sha256.
 *
 *   # 3. copy the jar to the primary and import it (cheap: hash + copy into the mirror):
 *   npx tsx scripts/mc-build-paper.ts --import /tmp/paper-26.2.jar --project paper --version 26.2 \
 *        --commit <40-hex> --sha256 <64-hex>
 *
 * Imported jars are `channel: self-built`, `provenance: built-from-git@<commit>`, shown
 * with a "self-built" badge on /admin/mc-mirror, and only used by the pin planner when no
 * official build is mirrored AND the official provider is failing — or when pinned
 * explicitly (scripts/mc-pin-jar.ts --build git-<short>).
 */
import fs from "node:fs/promises";
import { resolveGitBuildPlan, type GitProject } from "../lib/mcjars/providers/paper-git";
import { importLocalFile } from "../lib/mcjars/store";
import { mirrorReady } from "../lib/mcjars/config";

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`);
  return i > 0 ? process.argv[i + 1] : undefined;
}

async function main() {
  const project = (arg("project") ?? "paper") as GitProject;
  if (project !== "paper" && project !== "folia") throw new Error("--project paper|folia");
  const version = arg("version");
  if (!version || !/^\d+(\.\d+){1,3}$/.test(version)) throw new Error("--version <mc version> required");

  const importPath = arg("import");
  if (importPath) {
    const commit = arg("commit") ?? "";
    if (!/^[a-f0-9]{40}$/.test(commit)) throw new Error("--commit <40-hex git sha> required for --import");
    if (!(await mirrorReady({ create: true }))) throw new Error("mirror dataset missing — see docs (owner zfs command)");
    const build = `git-${commit.slice(0, 10)}`;
    const r = await importLocalFile({
      type: project,
      mcVersion: version,
      build,
      fileName: `${project}-${version}-${build}.jar`,
      srcPath: importPath,
      provenance: `built-from-git@${commit}`,
      expectSha256: arg("sha256"),
    });
    if (!r.ok) throw new Error(`import failed: ${r.error}`);
    console.log(`imported ${project} ${version} ${build} sha256=${r.sha256} (${(r.size / 1048576).toFixed(1)} MB) as channel self-built`);
    return;
  }

  const plan = await resolveGitBuildPlan(project, version);
  console.log(`project   ${plan.project}  (${plan.repo})`);
  console.log(`version   ${plan.mcVersion}  ref ${plan.ref}`);
  console.log(`jdk       ${plan.jdk}`);
  console.log(`tasks     ${plan.tasks.length ? plan.tasks.map((t) => `./gradlew ${t}`).join(" → ") : "(README had no recipe — the script discovers a create*PaperclipJar/BundlerJar task)"}`);
  console.log(`output    ${plan.outputDir}`);
  console.log(`source    ${plan.instructionsFromReadme ? "README of that ref" : "defaults + discovery (UNVERIFIED)"}`);
  const emit = arg("emit");
  if (emit) {
    await fs.writeFile(emit, plan.script + "\n", { mode: 0o755 });
    console.log(`wrote builder script → ${emit}  (copy it to a builder VM and run it there)`);
  } else {
    console.log("\n--- builder script (dry run; pass --emit <file> to save) ---\n" + plan.script);
  }
}

main().then(
  () => process.exit(0),
  (e) => {
    console.error(e instanceof Error ? e.message : e);
    process.exit(1);
  },
);

