/**
 * Minecraft server-software mirror (lib/mcjars) — recorded-fixture parser
 * tests for every provider, store layout/atomicity/checksum/eviction, the
 * serving route (incl. traversal), pin env/script generation per type,
 * availability/combo validation, quota logic and the Paper build-from-git plan.
 *
 *   npx tsx --test test/mcjars.test.ts
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import fsp from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";

process.env.MC_MIRROR_URL_SECRET = "test-secret-for-mcjars-0123456789";
process.env.MC_MIRROR_PUBLIC_URL = "https://nxeon.test";

import { parseMojangManifest, parseMojangVersion, type MojangManifest } from "../lib/mcjars/providers/mojang";
import { parseFillVersions, parseFillBuilds, fetchPaperV2, fetchPaperProject, type FillBuild } from "../lib/mcjars/providers/paper";
import { parsePurpurVersion } from "../lib/mcjars/providers/purpur";
import { parseFabric, parseQuilt } from "../lib/mcjars/providers/fabric";
import { parseForge, parseMavenVersions, parseNeoForge } from "../lib/mcjars/providers/forge";
import { parseBedrockLinks } from "../lib/mcjars/providers/bedrock";
import { parseBuildInstructions, chooseRef, buildPlan, defaultJdk } from "../lib/mcjars/providers/paper-git";
import { compareMcVersions, neoforgeToMc, nearestVersion, sortVersionsDesc, compareBuilds } from "../lib/mcjars/versions";
import {
  safeJoin,
  validSegment,
  mergeIndex,
  planRetention,
  writeFileAtomic,
  commitTmp,
  verifyBuild,
  downloadBuild,
  writeIndex,
  readIndex,
  importLocalFile,
  summarizeVersion,
} from "../lib/mcjars/store";
import { McHttp } from "../lib/mcjars/http";
import { serveMirrorFile, parseRange } from "../lib/mcjars/serve";
import { tokenFor, mirrorPath } from "../lib/mcjars/urls";
import { pinnedEnv, upstreamEnv, applyEnv, applyPinToSetupScript, stageScript, assertShellSafe, parseMarker, markerValue, type PinPlan } from "../lib/mcjars/pin";
import { pickBuild, resolveVersion, planPin } from "../lib/mcjars/plan";
import { fromIndex, checkComboIn, type Availability } from "../lib/mcjars/availability";
import { syncProvider } from "../lib/mcjars/sync";
import { applyGameVariant, wrapDockerGameService, buildGameSetupScript } from "../worker/game-variant";
import type { IndexBuild, TypeIndex, ProviderResult } from "../lib/mcjars/types";

const FX = path.join(process.cwd(), "test/fixtures/mcjars");
const fx = (n: string) => JSON.parse(fs.readFileSync(path.join(FX, n), "utf8"));
const fxText = (n: string) => fs.readFileSync(path.join(FX, n), "utf8");
const tmpRoot = () => fs.mkdtempSync(path.join(os.tmpdir(), "mcjars-test-"));
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const JAR = (n = 1000) => Buffer.concat([Buffer.from([0x50, 0x4b, 0x03, 0x04]), Buffer.alloc(n - 4, 7)]);

function fakeFetch(routes: Record<string, () => Response>): typeof fetch {
  return (async (input: RequestInfo | URL) => {
    const u = String(input);
    const h = routes[u];
    if (!h) return new Response("nope", { status: 404 });
    return h();
  }) as typeof fetch;
}
const noSleep = { sleep: async () => {} };

// ---------------------------------------------------------------------------
// Provider parsers (recorded fixtures, 2026-10-01)
// ---------------------------------------------------------------------------

test("mojang: releases only, newest first; server download with sha1+size; pre-1.2.5 has none", () => {
  const rel = parseMojangManifest(fx("mojang-manifest.json") as MojangManifest);
  assert.equal(rel[0].id, "26.3");
  assert.ok(rel.every((r) => !/snapshot/.test(r.id)));
  const c = parseMojangVersion("26.3", fx("mojang-version-26.3.json"))!;
  assert.equal(c.fileName, "minecraft_server.26.3.jar");
  assert.deepEqual(c.upstreamHash, { algo: "sha1", value: "33680f5f2ac32864d6d7cf5e56a705fdb3e05f4c" });
  assert.equal(c.size, 62294556);
  assert.equal(c.extra?.javaMin, 25);
  assert.equal(parseMojangVersion("1.0", fx("mojang-version-1.0.json")), null);
});

test("paper fill v3: versions + builds; channel mapping; sha256; newest first; beta-only 26.3", () => {
  const vs = parseFillVersions(fx("paper-v3-versions.json"));
  const ids = vs.map((v) => v.id);
  assert.ok(ids.includes("26.2") && ids.includes("1.8.8"));
  assert.equal(vs.find((v) => v.id === "26.3")!.javaMin, 25);
  const b262 = parseFillBuilds("paper", "26.2", fx("paper-v3-builds-26.2.json") as FillBuild[]);
  assert.ok(b262.length <= 10 && b262.length > 0);
  assert.equal(b262[0].build, "129");
  assert.equal(b262[0].fileName, "paper-26.2-129.jar");
  assert.equal(b262[0].channel, "stable");
  assert.match(b262[0].url, /^https:\/\/fill-data\.papermc\.io\//);
  assert.equal(b262[0].upstreamHash?.algo, "sha256");
  for (let i = 1; i < b262.length; i++) assert.ok(Number(b262[i - 1].build) > Number(b262[i].build));
  const b263 = parseFillBuilds("paper", "26.3", fx("paper-v3-builds-26.3.json") as FillBuild[]);
  assert.ok(b263.length > 0 && b263.every((b) => b.channel === "experimental"));
});

test("paper v2 is sunset upstream: fallback fails loudly, never 'no versions' silently", async () => {
  const sunset = fx("paper-v2-sunset.json");
  const http = new McHttp({ ...noSleep, maxRetries: 0, fetchImpl: fakeFetch({ "https://api.papermc.io/v2/projects/paper": () => Response.json(sunset) }) });
  await assert.rejects(() => fetchPaperV2(http, "paper", null), /sunset/);
  // v3 503 + v2 sunset → combined error naming both
  const http2 = new McHttp({
    ...noSleep,
    maxRetries: 0,
    fetchImpl: fakeFetch({
      "https://fill.papermc.io/v3/projects/paper/versions": () => new Response("down", { status: 503 }),
      "https://api.papermc.io/v2/projects/paper": () => Response.json(sunset),
    }),
  });
