function build(over: Partial<IndexBuild> & { build: string }): IndexBuild {
  return { channel: "stable", fileName: `paper-x-${over.build}.jar`, sourceUrl: "https://x/" + over.build, mirrored: false, ...over };
}
function ixWith(type: TypeIndex["type"], versions: Record<string, IndexBuild[]>): TypeIndex {
  const v: TypeIndex["versions"] = {};
  for (const [k, bs] of Object.entries(versions)) v[k] = summarizeVersion(bs, bs.some((b) => b.channel === "stable") ? "stable" : "experimental");
  return { schema: 1, type, updatedAt: new Date().toISOString(), source: "t", order: sortVersionsDesc(Object.keys(v)), versions: v };
}

