test("retention: hot = newest N + in-use; in-use and self-built never evicted; cold = latest only; budget", () => {
  const ix = ixWith("paper", {
    "26.2": [build({ build: "3" }), build({ build: "2" }), build({ build: "1", mirrored: true, size: 10 })],
    "1.8.8": [build({ build: "445", size: 10 }), build({ build: "440", mirrored: true, size: 10 })],
    "1.12.2": [build({ build: "1620", mirrored: true, size: 10 }), build({ build: "1619", mirrored: true, size: 10 }), build({ build: "git-x", channel: "self-built", mirrored: true, size: 10 })],
  });
  const plan = planRetention(ix, { keepHot: 2, hotVersions: 1, scope: "all", inUse: [{ type: "paper", mcVersion: "1.8.8", build: "440" }], maxBytes: 1e12, usedBytes: 0 });
  const dl = plan.download.map((d) => `${d.mcVersion}#${d.build.build}`);
  assert.ok(dl.includes("26.2#3") && dl.includes("26.2#2"), "hot version keeps 2 newest");
  assert.ok(dl.includes("1.8.8#445"), "in-use version is hot too");
  const ev = plan.evict.map((e) => `${e.mcVersion}#${e.build.build}`);
  assert.ok(ev.includes("26.2#1"), "old build of a hot version evicted");
  assert.ok(!ev.includes("1.8.8#440"), "in-use build never evicted");
  assert.ok(ev.includes("1.12.2#1619") && !ev.includes("1.12.2#1620"), "cold version keeps only its latest");
  assert.ok(!ev.some((e) => e.includes("git-x")), "self-built never auto-evicted");
  const tight = planRetention(ix, { keepHot: 2, hotVersions: 1, scope: "all", inUse: [], maxBytes: 15, usedBytes: 0, unknownSize: 100 });
  assert.ok(tight.skippedForBudget > 0, "budget stops further downloads");
  const hotOnly = planRetention(ix, { keepHot: 1, hotVersions: 1, scope: "hot", inUse: [], maxBytes: 1e12, usedBytes: 0 });
  assert.ok(!hotOnly.download.some((d) => d.mcVersion === "1.8.8"));
});

