test("retention: hot = newest N + in-use; in-use and self-built never evicted; cold = latest only; budget", () => {
  const ix = ixWith("paper", {
    "26.2": [build({ build: "3" }), build({ build: "2" }), build({ build: "1", mirrored: true, size: 10 })],
    "1.8.8": [build({ build: "445", size: 10 }), build({ build: "440", mirrored: true, size: 10 })],
    "1.12.2": [build({ build: "1620", mirrored: true, size: 10 }), build({ build: "1619", mirrored: true, size: 10 }), build({ build: "git-x", channel: "self-built", mirrored: true, size: 10 })],
  });
  const plan = planRetention(ix, { keepHot: 2, hotVersions: 1, scope: "all", inUse: [{ type: "paper", mcVersion: "1.8.8", build: "440" }], maxBytes: 1e12, usedBytes: 0 });
  const dl = plan.download.map((d) => `${d.mcVersion}#${d.build.build}`);
  assert.ok(dl.includes("26.2#3") && dl.includes("26.2#2"), "hot version keeps 2 newest");
  assert.ok(dl.includes("1.8.8#445"), "in-use version is hot too");
  const ev = plan.evict.map((e) => `${e.mcVersion}#${e.build.build}`);
  assert.ok(ev.includes("26.2#1"), "old build of a hot version evicted");
  assert.ok(!ev.includes("1.8.8#440"), "in-use build never evicted");
  assert.ok(ev.includes("1.12.2#1619") && !ev.includes("1.12.2#1620"), "cold version keeps only its latest");
  assert.ok(!ev.some((e) => e.includes("git-x")), "self-built never auto-evicted");
  const tight = planRetention(ix, { keepHot: 2, hotVersions: 1, scope: "all", inUse: [], maxBytes: 15, usedBytes: 0, unknownSize: 100 });
  assert.ok(tight.skippedForBudget > 0, "budget stops further downloads");
  const hotOnly = planRetention(ix, { keepHot: 1, hotVersions: 1, scope: "hot", inUse: [], maxBytes: 1e12, usedBytes: 0 });
  assert.ok(!hotOnly.download.some((d) => d.mcVersion === "1.8.8"));
});

test("syncProvider end-to-end (fake upstream): download, resumable cap, second run idempotent, refuses empty upstream", async () => {
  const root = tmpRoot();
  const jars: Record<string, Buffer> = { a: JAR(300), b: JAR(301) };
  let fail = false;
  const def = {
    type: "purpur" as const,
    label: "t",
    terms: "",
    ratePerMin: 6000,
    timeoutMs: 60_000,
    maxDownloadsPerRun: 1,
    enabled: () => true,
    fetch: async (): Promise<ProviderResult> =>
      fail
        ? { source: "t", versions: [], candidates: [] }
        : {
            source: "t",
            versions: [{ mcVersion: "26.3", channel: "stable" }, { mcVersion: "26.2", channel: "stable" }],
            candidates: [
              { type: "purpur", mcVersion: "26.3", build: "2", channel: "stable", fileName: "purpur-26.3-2.jar", url: "https://u/a", upstreamHash: { algo: "sha256", value: sha(jars.a) } },
              { type: "purpur", mcVersion: "26.2", build: "9", channel: "stable", fileName: "purpur-26.2-9.jar", url: "https://u/b", upstreamHash: { algo: "sha256", value: sha(jars.b) } },
            ],
          },
  };
  const opts = { root, inUse: [], usedBytesOtherTypes: 0, maxBytes: 1e9, keepHot: 1, hotVersions: 2, scope: "all" as const, fetchImpl: fakeFetch({ "https://u/a": () => new Response(jars.a), "https://u/b": () => new Response(jars.b) }) };
  const r1 = await syncProvider(def, opts);
  assert.equal(r1.stats.downloaded, 1);
  assert.equal(r1.stats.backlog, 1, "cap leaves a backlog for the next run");
  const r2 = await syncProvider(def, opts);
  assert.equal(r2.stats.downloaded, 1);
  const r3 = await syncProvider(def, opts);
  assert.equal(r3.stats.downloaded, 0, "nothing left to do");
  const ix = (await readIndex("purpur", root))!;
  assert.ok(ix.versions["26.3"].builds[0].mirrored && ix.versions["26.2"].builds[0].mirrored);
  fail = true;
  const r4 = await syncProvider(def, opts);
  assert.match(r4.stats.metadataError ?? "", /no versions/);
  assert.equal((await readIndex("purpur", root))!.order.length, 2, "index not wiped by an empty upstream answer");
});

