async function servedMirror() {
  const root = tmpRoot();
  const data = JAR(5000);
  const file = "paper-26.2-129.jar";
  const abs = safeJoin(root, "paper", "26.2", file);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, data);
  fs.writeFileSync(path.join(root, "secret.txt"), "TOP SECRET");
  await writeIndex(ixWith("paper", { "26.2": [build({ build: "129", fileName: file, mirrored: true, sha256: sha(data), size: data.length }), build({ build: "128", fileName: "paper-26.2-128.jar", mirrored: false })] }), root);
  return { root, data, file, tok: tokenFor("paper", "26.2", file) };
}
const req = (h: Record<string, string> = {}, method = "GET") => new Request("https://nxeon.test/x", { method, headers: h });

test("serve: 200 with body/ETag, HEAD, range 206, bad range 416, If-None-Match 304", async () => {
  const { root, data, file, tok } = await servedMirror();
  const segs = [tok, "paper", "26.2", file];
  const r = await serveMirrorFile(req(), segs, { root, rateLimit: false });
  assert.equal(r.status, 200);
  assert.equal(Buffer.from(await r.arrayBuffer()).equals(data), true);
  assert.equal(r.headers.get("etag"), `"${sha(data)}"`);
  assert.equal(r.headers.get("x-nxeon-sha256"), sha(data));
  const h = await serveMirrorFile(req({}, "HEAD"), segs, { root, rateLimit: false });
  assert.equal(h.status, 200);
  assert.equal(h.headers.get("content-length"), String(data.length));
  const p = await serveMirrorFile(req({ range: "bytes=10-19" }), segs, { root, rateLimit: false });
  assert.equal(p.status, 206);
  assert.equal(p.headers.get("content-range"), `bytes 10-19/${data.length}`);
  assert.equal(Buffer.from(await p.arrayBuffer()).equals(data.subarray(10, 20)), true);
  assert.equal((await serveMirrorFile(req({ range: "bytes=99999-" }), segs, { root, rateLimit: false })).status, 416);
  assert.equal((await serveMirrorFile(req({ "if-none-match": `"${sha(data)}"` }), segs, { root, rateLimit: false })).status, 304);
  assert.deepEqual(parseRange("bytes=-10", 100), { start: 90, end: 99 });
  assert.equal(parseRange("bytes=5-1", 100), "invalid");
  assert.ok(mirrorPath("paper", "26.2", file).startsWith(`/api/mcjars/${tok}/paper/26.2/`));
});

test("serve: bad token, unknown/unmirrored file, traversal, index.json, symlink → 404 (never another file)", async () => {
  const { root, file, tok } = await servedMirror();
  const cases: string[][] = [
    ["A".repeat(32), "paper", "26.2", file],
    [tok, "paper", "26.2", "paper-26.2-128.jar"],
    [tokenFor("paper", "26.2", "paper-26.2-128.jar"), "paper", "26.2", "paper-26.2-128.jar"],
    [tok, "paper", "..", "secret.txt"],
    [tok, "paper", "%2e%2e", "secret.txt"],
    [tok, "paper", "26.2", "..%2F..%2Fsecret.txt"],
    [tok, "paper", "26.2", "index.json"],
    [tokenFor("paper", "26.2", "index.json"), "paper", "26.2", "index.json"],
    [tok, "..", "26.2", file],
    [tok, "paper", "26.2"],
    [tok, "paper", "26.2", file, "extra"],
  ];
  for (const c of cases) {
    const r = await serveMirrorFile(req(), c, { root, rateLimit: false });
    assert.equal(r.status, 404, c.join("/"));
    assert.ok(!(await r.text()).includes("SECRET"));
  }
  // A symlink planted where a mirrored file should be is not followed.
  const abs = safeJoin(root, "paper", "26.2", file);
  fs.rmSync(abs);
  fs.symlinkSync(path.join(root, "secret.txt"), abs);
  assert.equal((await serveMirrorFile(req(), [tok, "paper", "26.2", file], { root, rateLimit: false })).status, 404);
});

