};
if (init.cond?.etag) headers["If-None-Match"] = init.cond.etag;
if (init.cond?.lastModified) headers["If-Modified-Since"] = init.cond.lastModified;
let lastErr: unknown;
for (let attempt = 0; attempt <= maxRetries; attempt++) {
  this.checkDeadline();
  await this.pace(url);
  this.requests++;
  // Two clocks: response HEADERS must arrive within 30 s (a CDN that silently
  // stalls bot traffic — minecraft.net does — fails fast instead of eating the
  // provider's whole budget), and the whole request incl. body within timeoutMs.
  const ctl = new AbortController();
  const headerTimer = setTimeout(() => ctl.abort(new Error(`no response headers from ${url} within 30s`)), 30_000);
  const totalTimer = setTimeout(() => ctl.abort(new Error(`request to ${url} exceeded ${init.timeoutMs ?? 30_000}ms`)), init.timeoutMs ?? 30_000);
  totalTimer.unref?.();
  try {
    const res = await this.fetchImpl(url, {
      ...init,
      headers,
      redirect: "follow",
      signal: init.signal ?? ctl.signal,
    }).finally(() => clearTimeout(headerTimer));
    if (res.status === 429 || res.status >= 500) {
      clearTimeout(totalTimer);
      lastErr = new HttpError(res.status, url);
      try {
        await res.arrayBuffer();
      } catch {
        /* drain */
      }
      if (attempt === maxRetries) throw lastErr;
      this.retries++;
      await this.sleep(McHttp.backoffMs(attempt, res.headers.get("retry-after")));
      continue;
    }
    return res;
  } catch (e) {
    clearTimeout(totalTimer);
    if (e instanceof HttpError) throw e;
    lastErr = e;
    if (attempt === maxRetries) throw e;
    this.retries++;
    await this.sleep(McHttp.backoffMs(attempt));
  }
}
throw lastErr;

