import { chromium } from "playwright";
import fs from "node:fs";
const tok = JSON.parse(fs.readFileSync("/tmp/mcj-tokens.json", "utf8"));
const out = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/mcmirror";
fs.mkdirSync(out, { recursive: true });
const b = await chromium.launch();
async function shot(name, host, cookie, url, opts = {}) {
  for (const [vw, vh, tag] of [[1366, 900, "desktop"], [390, 844, "mobile"]]) {
    const ctx = await b.newContext({ viewport: { width: vw, height: vh } });
    await ctx.addCookies([{ name: "nxeon_session", value: cookie, domain: host, path: "/" }, { name: "nxeon_tour_optout", value: "1", domain: host, path: "/" }]);
    const p = await ctx.newPage();
    const errs = [];
    p.on("pageerror", (e) => errs.push(String(e)));
    const r = await p.goto(`http://${host}:3123${url}`, { waitUntil: "networkidle", timeout: 180000 }).catch((e) => ({ status: () => "ERR " + e.message }));
    if (opts.after) await opts.after(p).catch((e) => errs.push("after: " + e.message));
    await p.waitForTimeout(1500);
    await p.screenshot({ path: `${out}/${name}-${tag}.png`, fullPage: !!opts.full });
    console.log(name, tag, r.status?.(), p.url().replace(/http:\/\/[^/]+/, ""), errs.slice(0, 3).join(" | "));
    if (opts.text) console.log("  text:", (await opts.text(p)).slice(0, 600));
    await ctx.close();
  }
}
const mode = process.argv[2];
if (mode === "admin") await shot("admin-mc-mirror", "localhost", tok.admin, "/admin/mc-mirror", { full: true, text: (p) => p.innerText("main").catch(() => p.innerText("body")) });
if (mode === "settings") await shot("settings", "127.0.0.1", tok.cust, `/dashboard/servers/${tok.server}?tab=settings`, {
  full: true,
  text: async (p) => { const t = await p.innerText("body"); const i = t.indexOf("Server type"); return t.slice(Math.max(0, i - 50), i + 700); },
});
if (mode === "wizard") await shot("wizard", "127.0.0.1", tok.cust, `/dashboard/deploy?service=game&gameFamily=minecraft&gameVariant=paper`, {
  full: true,
  after: async (p) => { await p.waitForTimeout(3000); const el = await p.$("text=Minecraft version"); if (el) await el.scrollIntoViewIfNeeded(); },
  text: async (p) => { const t = await p.innerText("body"); const i = t.indexOf("Minecraft version"); return i < 0 ? "(no Minecraft version field visible) " + t.slice(0, 300) : t.slice(i, i + 500); },
});
await b.close();
EOF
timeout 600 node .mcj-tmp/shots.mjs admin 2>&1 | tail -30

